        }
    }

    // MUTATION 4: endgame residual sweep — in the final stretch, weight
    // post-residual waste super-linearly to squeeze the last bins.
    if progress > 0.75 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.85 * pr * pr / cap * (progress - 0.75) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A residual is "dead" if it's too small to hold even the smallest plausible item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // impossible, shouldn't happen, but guard
    }
    // Non-linear dead-space penalty: gaps that are small but nonzero are worst.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 3.0; // steep penalty for tiny unusable gaps
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream.
        score += 15.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
        // But if this bin would leave no dead space and existing fits are poor, allow it.
        if post_residual == 0 {
            score -= 40.0;
        }
    } else {
        // Slight reward for keeping bins consolidated when few are open.
        score -= 2.0 / open_bins_count.max(1) as f64;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && (post_residual as f64) == next_item_size as f64 {
        score -= 30.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item can't use this gap: the gap is likely dead space
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

