    // get closed first, keeping loose bins flexible).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1u32; // sizes start at 1; treat tiny gaps as dead only if truly unusable
    // Dead space = residual too small for any plausible future item.
    // Use a graded penalty: gaps below ~1/4 capacity are increasingly toxic.
    let quarter = (bin_capacity / 4) as f64;
    if (post_residual as f64) < quarter {
        let deadness = 1.0 - (post_residual as f64) / quarter;
        score += 25.0 * deadness * deadness; // quadratic dead-space penalty
    }

    // Perfect fit reward: near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; slight penalty since this chain ends.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large post residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.5 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Open-bins pressure: many open bins -> favor consolidating into existing ones,
    // penalize the new-bin candidate more.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 40.0 + 3.0 * open_bins_count as f64 + 0.3 * mean_residual;
    } else {
        // Existing bin: reward using it, scaled by how many bins are open.
        score -= 2.0 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, be more conservative with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward small post-residuals non-linearly (waste penalty grows fast).
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64).powi(3) * 40.0;
    }

    // 2-step lookahead: if next item exactly fills the post residual,
    // this bin is a perfect 2-item chain — strongly favor it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    }
    // If next item fits in the post residual, mild reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - (slack / bin_capacity as f64) * 15.0;
    }
    // Penalize leaving post_residual too small for any plausible future item
    // (dead space below minimum item size 1..=10 range: treat <10 as likely waste).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Relative to mean residual: placing into a below-average-residual bin
    // (tighter bin) is good; into an above-average bin is worse.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if next item is large and current item is large, a fresh bin
        // chains well: soften the penalty.
        if item_size >= 50 && next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build diversity);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: squared waste penalty.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize the brand-new empty bin candidate unless the fit elsewhere is bad:
    // a fresh bin is only attractive when the item is large relative to residuals
    // or when open bins are very full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill_pressure = 1.0 - (mean_residual / bin_capacity as f64);
        score += 150.0
            - 100.0 * fill_pressure
            - 50.0 * progress
            - (item_size as f64 / bin_capacity as f64) * 80.0;
        // If the next item would also need a bin, opening one now is fine.
        if next_item_size > post_residual && next_item_size > 0 {
            score -= 60.0;
        }
    }

    // Lookahead coupling: leaving exactly enough room for the next item is ideal.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 120.0;
        } else if gap > 0 {
            // Penalize residuals that are just slightly too small for the next item (dead space).
            score += (gap as f64).min(30.0) * 0.5;
        }
    }

    // Prefer filling bins that are already heavily committed (fewer bins wasted).
    let used = (bin_capacity - bin_residual) as f64;
    score -= used * 0.3;

    // Mild penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 2.0;

    // Reward bins whose residual is close to the global mean residual (harmonize states).
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    // Early stream: slightly prefer consolidation to build dense bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.9 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, tolerate larger residuals (favor new-bin flexibility);
    // later, punish residual waste more aggressively (quadratic growth).
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (0.5 + progress) + norm_pr * progress * progress;
    score += 30.0 * coupling;

    // Reward tight fits: perfect fit gets a strong bonus.
    if pr == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize when open bins exist and stream is advanced,
    // reward early when mean residual is high (fragmentation elsewhere).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 * (1.0 - progress) * (1.0 - progress);
        score += new_bin_penalty;
        if mean_residual > 0.0 {
            score -= (mean_residual / cap) * 8.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 12.0;
    }
    // If next item is large and won't fit, mild penalty for wasting this bin's space.
    if next_item_size as f64 > pr && next_item_size > 0 {
        score += 4.0 * (1.0 - progress);
    }

    // Slight penalty proportional to number of open bins to discourage sprawl.
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes
    // modulo 10 and capacity-fraction bands. Small leftovers in "nice" classes
    // (multiples of 10) are more reusable -> reward them.
    let pr = post_residual;
    if pr > 0 {
        let mod_class = pr % 10;
        // Penalize leftovers that are not multiples of 10 (harder to fill exactly)
        score += (mod_class as f64) * 1.5;

        // Fraction-of-capacity bands
        let frac = pr as f64 / cap;
        if frac <= 0.05 {
            score -= 30.0; // nearly perfect fill
        } else if frac <= 0.15 {
            score -= 10.0;
        } else if frac <= 0.30 {
            score -= 3.0;
        } else if frac > 0.80 {
            score += 25.0; // wasteful large leftover
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Integer-division threshold on post_residual vs next item
    if next_item_size > 0 && pr >= next_item_size {
        // This bin can also host the lookahead item: strong reward,
        // especially if the pair fits snugly (pr - next_item small).
        let after_next = pr - next_item_size;
        score -= 12.0;
        if after_next <= 5 {
            score -= 15.0; // double snug fit
        }
        if after_next % 10 == 0 && after_next > 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // Lookahead cannot use this leftover: penalize proportionally
        let gap = (next_item_size - pr) as f64;
        score += gap * 0.35;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin is opened.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when item is large relative to capacity and current residuals are messy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Base reluctance to open a bin
        score += 8.0;
        // Large items leave predictable residuals; slightly favor new bins early
        if item_frac > 0.5 {
            score -= 4.0 * (1.0 - progress);
        }
        // If open bins are on average roomy, prefer them over a new bin
        score += (mean_residual / cap) * 6.0;
        // Many open bins: keep consolidation pressure
        score += open_bins_count as f64 * 0.4;
    } else {
        // Slight consolidation preference: fewer open bins is better
        score -= open_bins_count as f64 * 0.15;
        // Prefer tighter bins (smaller residual) mildly beyond raw post_residual
        score += (bin_residual as f64 / cap) * 2.0;
    }

    // Progress-aware tightness bonus: late in the stream, squeeze harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are pure waste; penalize any small unusable gap heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that no plausible future item (1..=100) can use well:
    // a gap is "dead" if it's tiny; a gap that exactly fits is golden.
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if the next item fits into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here: this gap may become dead space
        score += 10.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer existing bins
    // over creating new ones (new bin raises open_bins_count cost).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; also compare against
        // mean residual of open bins — if open bins are quite full, a new
        // bin is more acceptable.
        score += 30.0 + pressure * 2.0 - (mean_residual / bin_capacity as f64) * 20.0;
    } else {
        // Slight bonus for placing into bins below mean residual (balancing).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches next item (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Partial lookahead credit: how much of next item fits into the chain.
            let cover = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * cover * cover;
        } else {
            // Dead space penalty scaled by how badly next item misses.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.6;
        }
        // Penalize tiny unusable slivers after considering next item.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins below mean residual are "waste candidates";
    // filling them is good, so reward placing into low-residual bins.
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (mean_residual - resid) / mean_residual;
        score -= 10.0 * rel.clamp(-1.0, 1.0);
    }

    // Last-chance bonus: sole fitting bin should absorb the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the next item would exactly fill the fresh bin's residual after this item,
        // opening a fresh bin becomes attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer bins whose remaining residual after placement stays "chunky" (>= 20),
    // mildly, to keep future flexibility.
    if post_residual >= 20 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize large dead space relative to capacity, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * (0.5 + progress);

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted potential.
        let waste_gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 6.0 * (waste_gap / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers),
    // but only mildly so we don't destroy big usable spaces.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.5 * (open_bins_count as f64) * dead;

    // New-bin candidate handling: only open a new bin if the item is large
    // (would leave a very awkward residual in existing bins) or no good fits exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Large items justify a fresh bin more than small ones.
        score -= 0.4 * item_size as f64;
        // If the next item is also large, a fresh bin can host both -> cheaper.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += 25.0 * progress;
        // If only one bin fits the item, opening a new bin is wasteful.
        if fitting_bins_count <= 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr as f64;

    // Non-linear penalty on unusable residual, modulated by stream progress:
    // small residuals become progressively more penalized later in the stream.
    let deadness = (1.0 - norm_pr).powi(3);
    score += 40.0 * deadness * (0.3 + 0.7 * progress);

    // Smooth coupling: residual^2 scaled by progress rewards tight fits early,
    // punishes loose fits late.
    score += (norm_pr * norm_pr) * cap * (0.2 + 0.8 * progress);

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 {
        let fits_next = if next_item_size <= post_residual { 1.0 } else { 0.0 };
        let slack = (post_residual as f64 - next_item_size as f64).abs();
        score -= 25.0 * fits_next * (1.0 - slack / cap);
        // Penalize when post residual just misses the next item (near-miss waste)
        let near_miss = ((next_item_size as f64 - pr) / cap).max(0.0).min(0.2);
        score += 15.0 * near_miss * (1.0 - fits_next);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins whose residual deviates below mean
    // (consolidate small leftovers), smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev - 5.0 * dev;

    // Mild preference for fewer open bins as stream matures.
    score += open_bins_count as f64 * 0.5 * progress;

    // New-bin candidate: make empty bin attractive only when its score
    // (residual = capacity) is competitive; smooth logistic gate on progress.
    let is_new = (bin_residual == bin_capacity) as i32 as f64;
    let gate = 1.0 / (1.0 + (-8.0 * (progress - 0.5)).exp());
    score += is_new * (20.0 * gate + 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: which capacity-fraction band it falls into.
    // Bands: [0..=10] perfect closure, (10..=25] awkward dead zone, (25..=50] half-class,
    // (50..=100] roomy class.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect closure is ideal
    } else if post_residual <= 10 {
        score -= 40.0; // near-closure still great
    } else if post_residual <= 25 {
        score += 30.0; // awkward dead zone: small items unlikely to reuse
    } else if post_residual <= 50 {
        score -= 5.0; // half-class residuals are reusable
    } else {
        score += 10.0; // roomy but wasteful for a big item
    }

    // Integer-division harmonic: residual / 25 quarter-class bonus.
    let quarter_class = post_residual / 25;
    score -= match quarter_class {
        0 => 8.0,
        1 => 4.0,
        2 => 2.0,
        _ => 0.0,
    } as f64;

    // Lookahead coupling: if next item exactly fits post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // modular compatibility: does next item leave a harmonic residue?
            let nxt_res = post_residual - next_item_size;
            if nxt_res <= 10 {
                score -= 25.0;
            } else if nxt_res <= 25 {
                score += 5.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item can't use this bin's residue; penalize leaving residue it can't touch
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it moderately attractive only when residuals are fragmented
    // or the item is large relative to all residuals.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = (item_size as f64) > 0.7 * cap;
        if large_item || (open_bins_count > 3 && fragmentation < 0.3) {
            score -= 20.0;
        } else {
            score += 25.0; // discourage opening bins when existing ones suffice
        }
    }

    // Slight preference for tighter fits as the stream progresses (waste less early room).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (item_size as f64 / cap) * 10.0;

    // Tie-break: prefer bins whose residual is a multiple of 10 (harmonic alignment).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: residuals that are too small for the
        // smallest possible item (1) are pure waste; anything below a typical
        // small-item threshold is heavily penalized (non-linearly).
        let r = post_residual as f64;
        if post_residual <= 10 {
            score += 60.0 + (10.0 - r) * 8.0; // tiny gap = dead space
        } else if post_residual <= 25 {
            score += 15.0 + (25.0 - r) * 1.5; // moderately awkward gap
        }
        // Reward gaps that can still host the lookahead item (k=2 lookahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0 + next_item_size as f64 * 0.3;
        }
        // Penalize if the leftover gap cannot fit the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Open-bin pressure: prefer reusing existing bins; penalize spreading out.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when the item nearly fills it
    // (i.e., item_size is large) and existing bins are crowded.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score += 40.0 - fill * 90.0; // big items make a fresh bin cheap
        score += open_bins_count as f64 * 2.0;
    }

    // Mild alignment with global mean residual: placing into bins that keep
    // the fleet near the mean residual is slightly preferred.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Late in the stream, tighten up: dead space matters more when few items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in the post residual,
    // this is a two-item perfect packing — reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step_waste = post_residual - next_item_size;
        score -= 50.0 + (100.0 - two_step_waste as f64) * 0.5;
        if two_step_waste == 0 {
            score -= 300.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space proportional to closeness
        // of post_residual to next_item_size (near-miss = big waste).
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 20.0 {
            score += (20.0 - gap) * 8.0;
        }
    }

    // Prefer bins whose residual is small relative to mean (tight packing).
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open new bin anyway
        } else if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            // New bin can host both current and next item: attractive.
            score -= 250.0;
        }
        // Late in the stream, avoid opening bins with large expected waste.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild penalty for leaving residuals too small to ever be useful
    // (below minimum plausible item size of 1, only tiny slivers matter).
    if post_residual > 0 && post_residual < 5 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize creating unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward residual space that can host the next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize residuals that are just barely too small for the next item (trap states).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward residual large enough for next item plus slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins fit
    // the item or when global residuals are still large.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count > 0 {
            score += 15.0 * fitting_bins_count as f64;
        }
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If global mean residual is small, new bin is attractive.
        score -= (mean_residual - 50.0).max(0.0) * 0.1;
        // If next item is huge, keep a fresh bin available.
        if next_item_size >= 70 {
            score -= 6.0;
        }
    } else {
        // Mild preference for consolidating into emptier open bins when many are open.
        if open_bins_count > 8 && post_residual < 30 {
            score -= 3.0;
        }
    }

    // Prefer larger post_residual slightly when it stays reusable (>= typical item).
    if post_residual >= 40 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = r / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = r * (1.0 + 0.5 * progress * fit_norm);

    // Penalize large dead space more than linearly (quadratic waste), modulated by progress.
    score += 0.35 * fit_norm * fit_norm * cap * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size.
    score -= 12.0 * (1.0 - fit_norm) * (item_size as f64 / cap);

    // Lookahead: bonus if next item fits the resulting residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            score -= 8.0 * (1.0 - nx / cap) * (1.0 - progress * 0.5);
        } else {
            score += 4.0 * (nx - r) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_norm) * progress;

    // Deviation from mean residual: prefer bins near/below mean to balance loads.
    score += 0.2 * (r - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Dead-space penalty grows superlinearly in the "unusable" middle bands.
    // Residuals in (0,10] are effectively perfect; (10,20] good; large residuals wasteful
    // unless a new item can fill them.
    if post_residual == 0 {
        score -= 50.0; // perfect fit: strong reward
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else {
        // superlinear waste penalty
        score += (frac * frac) * 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the hole
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 15.0 * fill;
        } else {
            // next item cannot use this residual: penalize leftover a bit more
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (pristine bin): neutral-ish baseline; discourage when open bins fit well,
    // encourage when current placement would strand a big residual.
    if bin_residual == bin_capacity {
        // baseline score equals post_residual (= capacity - item_size); rebase it
        score = cap - item_size as f64;
        score += 8.0 * open_bins_count as f64; // mild cost to open yet another bin
        if fitting_bins_count > 0 {
            score += 15.0; // prefer existing bins when any fit
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0; // fresh bin gives room for the next item
        }
    }

    // Mean-residual coupling: when open bins are generally tight, conserve them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual < 15.0 && bin_residual >= item_size {
        score -= 5.0 * (1.0 - progress); // early stream: keep tight bins alive
    }

    // Modulo-class tiebreak: prefer residuals that are multiples of common item sizes.
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 2.0;
            break;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item (1) are fine,
    // but small-but-nonzero gaps that nothing can usefully fill are waste.
    // Penalize gaps in the "unusable" band [1, 10] heavily.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: mild penalty.
        score += 8.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // fuller bins (low post_residual) rather than spreading; add pressure term.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is below mean residual (i.e., fuller bins)
    // to keep a spread of large residuals for large future items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // (would leave tiny unusable gaps everywhere) or no bin fits well.
    if bin_residual == bin_capacity {
        let waste_if_forced = if post_residual >= 1 && post_residual <= 10 { 40.0 - 3.0 * post_residual as f64 } else { 0.0 };
        // Base cost of opening a new bin.
        score += 35.0;
        // But if the item is large relative to capacity, a fresh bin is good.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 45.0;
        }
        // If placing in an existing bin would strand dead space, favor new bin.
        score -= waste_if_forced;
        // Fewer open bins -> cheaper to open a new one early on.
        score -= 2.0 * (10usize.saturating_sub(open_bins_count)) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item fits exactly-ish into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.6 * slack; // perfect 2-step fill is best
        if slack == 0.0 {
            score -= 40.0; // exact chain match: huge bonus
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize more when post residual is small dead space
        score += 0.8 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Penalize dead space below the smallest possible item (1..100 unknown, assume ~10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Compare against mean residual: bins below mean residual are "tighter", prefer them
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize slightly unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 12.0 - 0.1 * item_size as f64;
        // but if next item also nearly fills a fresh bin, opening is fine
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 30.0;
        }
    }

    // Later in the stream: be more conservative, favor tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: square the residual waste so near-perfect fills dominate.
    score += (post_residual as f64 / cap).powi(2) * 30.0;

    // Reward bins whose residual is "shaped" by past placements (partially filled bins
    // are more valuable to close out than fresh ones).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 12.0;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits but not perfectly: mild bonus proportional to leftover after next.
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / cap));
        } else {
            // Next item won't fit here: penalize leaving residual just below next item size
            // (dead-space trap), scaled by how close it is to fitting.
            let gap = nxt - post_residual as f64;
            if gap < 10.0 {
                score += (10.0 - gap) * 1.5;
            }
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= fill_ratio * 20.0;
    }

    // Last-chance bin: if this is the only bin that fits the item, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (mean_residual / cap).max(0.01);
        // Penalize new bins early / when open bins still have plenty of room.
        score += 15.0 + pressure * 2.0;
        // But if the item is large and mean residual is low, new bin becomes attractive.
        score -= (item_size as f64 / cap) * 20.0 * (1.0 - (mean_residual / cap).min(1.0));
    }

    // Time horizon: late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post_residual as f64 / cap);

    // Global fragmentation: many open bins with high mean residual -> encourage using them up.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_frac = item_size as f64 / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * poly * (0.5 + progress);

    // Dead-space penalty grows smoothly with progress
    score += 25.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post residual) more strongly late in stream
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead: favor bins whose post residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - pr / nxt.max(1.0)) * (0.5 + progress);
        }
    }

    // Mild preference for consolidating when many bins open
    score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - norm_pr);

    // Align with mean residual state
    score += 3.0 * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more likely to be closed out usefully.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Class bonus: exact fills are perfect; residues divisible by small
    // harmonics (10, 20, 25, 50) are reusable by typical item sizes.
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 12.0;
        if pr % 50 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 4.0; }
    } else if pr <= 10 {
        score -= 20.0; // tiny dead space, effectively closed bin
    } else {
        // penalize awkward residues in (10, 20) and prime-ish gaps
        score += 6.0;
        if pr < 20 { score += 5.0; }
    }

    // Fraction-of-capacity class of post residual
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 10.0; // bin still half open, plenty reusable
    } else if frac > 0.25 {
        score -= 3.0;
    } else if frac > 0.0 {
        score += 4.0; // small but awkward leftover
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly reward this bin (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let nxt_pr = pr - next_item_size;
            if nxt_pr % 10 == 0 { score -= 10.0; }
            if nxt_pr <= 10 { score -= 8.0; }
            score -= (pr - next_item_size) as f64 * 0.05;
        } else {
            // next item won't fit here; slight penalty if this was the only option
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Late in the stream, consolidate harder to avoid straggler bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Spread penalty: keep residuals near the mean to preserve packing harmony.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    // New-bin candidate: make it attractive only when it's genuinely better.
    if bin_residual == bin_capacity {
        // fresh bin has full residual; base score already high (post_residual = cap)
        // give it a mild handicap so only bad fits into open bins trigger it
        score += 8.0;
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Mild preference for tighter fits overall
    score += (item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: cube the residual waste ratio so near-perfect fills dominate even more.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    score += pr_norm.powi(2) * 30.0 + pr_norm.powi(3) * 40.0;

