    // Perfect-fit snap: exact fill of the bin is always the top priority.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual) — already encoded by starting point.

    // Aggressive 2-step lookahead: strongly reward bins where the NEXT item
    // exactly or nearly fits into the post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            // Perfect chain: next item exactly fills the bin.
            score -= 30.0 * (1.0 - slack_after_next / bin_capacity as f64);
            // Extra reward for exact match (dead space = 0 after two placements).
            if slack_after_next == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item does NOT fit after this placement: penalize proportionally
            // to how stranded the next item would be, unless this bin becomes
            // perfectly full now.
            if post_residual == 0 {
                score -= 20.0; // bin closed exactly, chain irrelevant
            } else {
                let strandedness = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
                score += 15.0 * strandedness;
            }
        }
    } else {
        // Last item: just close bins as tightly as possible.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are the
    // "small leftover" bins — good to fill them up and eliminate them.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 8.0 * (dev / bin_capacity as f64);
    } else {
        score += 4.0 * ((-dev) / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the ONLY bin that fits, avoid opening a new
    // bin unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current item is huge (poor fit elsewhere) or many bins are open and
    // fragmented. Penalize default new-bin choice mildly otherwise.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 18.0 - 6.0 * fragmentation;
        if item_size >= bin_capacity / 2 {
            score -= 12.0; // big items deserve a fresh bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can chain the next item too
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate
    // harder (fewer wasted near-empty bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
