    score += (post_residual as f64 / cap).powi(2) * 35.0;

    // Reward partially filled bins: closing them out is valuable
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 10.0;

    // Lookahead: exact 2-step chain is best
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
