    // Tiny dead space is nearly unusable
    if post_residual > 0 && post_residual < 8 {
        score += 28.0;
    }

    // Tighter-than-mean bins are preferred
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 + (bin_residual - item_size) as f64 * 0.08;
    }

    // New-bin candidate: only attractive when open bins are fragmented or item is large
    if bin_residual == bin_capacity {
