            score += 2.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Time horizon: early in the stream, be pickier (avoid wasting bins early);
    // late in the stream, just close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than opening new ones.
    if open_bins_count > 0 {
        score -= 2.0 * (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: empty bin has all the space, but opening a new bin
    // should only win when the item is large relative to available fits.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += 10.0 + 8.0 * (1.0 - (item_size as f64 / bin_capacity as f64)) - scarcity;
        // Late in stream, new bins are cheaper to open
        score -= 6.0 * progress;
    }

    // Mild penalty for leaving residual much larger than the next item
    // (wasteful gap that nothing will fill).
    if next_item_size > 0 && post_residual > next_item_size + 40 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
