    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Pairing heuristic: prefer bins whose residual is close to the next item's size
    // even if not exact (soft lookahead matching), scaled by stream progress.
    if next_item_size > 0 && post_residual >= next_item_size {
        let closeness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= closeness * progress * 10.0;
    }

