pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: wasted space, weighted more as stream progresses (endgame tightness)
    let mut score = pr * (0.6 + 0.8 * t * t);

    // Non-linear penalty for awkward residual sizes (polynomial coupling):
    // residuals that are too small to be useful later get penalized smoothly.
    let usefulness = (x * (1.0 - x)).sqrt().max(0.0); // peaks at x=0.5
    score -= usefulness * cap * (0.25 + 0.35 * t);

    // Prefer filling bins tightly relative to current mean residual level
    let m = mean_residual / cap;
    score += (x - m).abs() * cap * 0.3 * (1.0 - t);

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 60.0 * t;
    }

    // Crowding: many open bins -> favor consolidation of large residuals
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += x * x * cap * 0.1 * crowd.min(4.0);

    // Lookahead coupling: if next item could fit in the post residual,
    // reward leaving that exact space; otherwise penalize mismatch.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) as f64;
            score -= (1.0 - slack / cap) * 25.0 * (1.0 - t);
        } else {
            score += (nx - pr).min(cap) * 0.5 * (0.5 + t);
        }
    }

    // New-bin candidate: keep it slightly unattractive unless current fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 - 25.0 * t + 10.0 * (1.0 - usefulness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

