    // near-fit creates a chain bonus scaled by how much would remain after.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 45.0;
        } else if post >= nxt {
            let after = (post - nxt) / cap;
            // Bonus peaks when the leftover after next placement is small or exactly
            // matches a "typical" small residual; penalize mid-range leftovers.
            if after < 0.12 {
                score -= 14.0 * (1.0 - after);
            } else {
