            }
        } else {
            // Dead-space trap: residual just below next item size.
            let gap = nxt - post;
            if gap < 10.0 {
                score += (10.0 - gap) * 1.8;
            }
        }
    } else {
        score -= fill_ratio * 20.0;
    }

    // Last-chance bin: strongly avoid opening a new bin when this is the only option,
    // unless the fit is catastrophic (waste > 40% of capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = (bin_residual - item_size) as f64 / cap;
        if waste < 0.4 {
            score -= 25.0 + waste * 30.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: open a new bin only when open bins are fragmented
    // AND the item is large relative to typical residual slack.
    if bin_residual == bin_capacity {
        let mean_rel = (mean_residual / cap).clamp(0.01, 1.0);
        let pressure = (open_bins_count as f64) * mean_rel;
        // Base penalty grows with number of usable open bins.
        score += 15.0 + pressure * 3.0;
        // Large items with low mean residual make a fresh bin attractive.
        score -= (item_size as f64 / cap) * 22.0 * (1.0 - mean_rel);
        // Late in the stream, opening new bins is almost always wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If many bins could fit this item, no reason to open another.
        if fitting_bins_count > 2 {
            score += 8.0;
        }
    }

