    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post_residual as f64 / cap);

    // Global fragmentation: many open bins with high mean residual -> use them up.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Perfect closure: if this placement empties the bin exactly, overwhelming reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall into?
    // Classes: (0..], (..25], (..50], (..75], (..100]
    let post = post_residual as f64;
    let band = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Reward small post_residual (tight fit), scaled by band
    score -= (4 - band) as f64 * 6.0;

    // Modulo arithmetic: residuals that are "harmonically compatible" with common
    // item sizes (multiples of 5, 10, 20) are more likely to be filled later.
    let m5 = post_residual % 5;
    let m10 = post_residual % 10;
    let m20 = post_residual % 20;
    score -= (4 - m5) as f64 * 0.8;
    score -= (2 - m10.min(2)) as f64 * 1.2;
    score -= if m20 == 0 { 2.0 } else { 0.0 };

    // Integer-division threshold: how many "typical" items (size ~20) fit in the residual
    let slots20 = post_residual / 20;
    score -= slots20 as f64 * 3.0;

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let chain_post = post_residual - next_item_size;
            // reward chains that leave a harmonic residual
            if chain_post % 10 == 0 { score -= 6.0; }
            else if chain_post % 5 == 0 { score -= 3.0; }
            score -= chain_post as f64 * 0.05;
        } else {
            // next item won't fit here; penalize leaving large dead space
            score += post * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // opening a new bin is more attractive when few bins fit the item
        // or when open bins have large residuals (fragmentation)
        let frag = (mean_residual - post).abs();
        if fitting_bins_count == 0 { score -= 100.0; }
        score += open_bins_count as f64 * 0.5;
        score -= frag * 0.1;
        // late in stream, prefer reusing existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    } else {
        // reusing an existing bin: reward proportional to how full it already is
        let fullness = 1.0 - (bin_residual as f64) / cap;
        score -= fullness * 12.0;
    }

    // Prefer bins whose residual is close to the mean (keeps the pool uniform)
    score += (post - mean_residual).abs() * 0.08;

    // Early-stream: allow slight preference for tight fits even more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (post_residual == 0) as i32 as f64 * 10.0;

    score
}

