        if post_residual as f64 == nxt {
            score -= 45.0; // exact chain match: huge bonus
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            if slack < 10.0 {
                score -= 10.0; // near-exact second fill
            }
        } else {
            // Dead-space trap: residual just below next item size.
            let gap = nxt - post_residual as f64;
            if gap < 12.0 {
                score += (12.0 - gap) * 1.6;
            }
        }
    } else {
        score -= fill_ratio * 20.0; // last item: pack fullest
    }

    // Tiny unfillable residual penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Tighter-than-mean bins preferred.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate: penalize unless item is large or pairs with next item.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (mean_residual / cap).max(0.01);
        score += 15.0 + pressure * 2.0;
        score -= (item_size as f64 / cap) * 20.0 * (1.0 - (mean_residual / cap).min(1.0));
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 30.0;
        }
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post_residual as f64 / cap);

    // Global fragmentation: encourage consuming open bins with slack.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A residual is "dead" if it's too small to hold even the smallest plausible item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // impossible, shouldn't happen, but guard
    }
    // Non-linear dead-space penalty: gaps that are small but nonzero are worst.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 3.0; // steep penalty for tiny unusable gaps
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream.
        score += 15.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
        // But if this bin would leave no dead space and existing fits are poor, allow it.
        if post_residual == 0 {
            score -= 40.0;
        }
    } else {
        // Slight reward for keeping bins consolidated when few are open.
        score -= 2.0 / open_bins_count.max(1) as f64;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && (post_residual as f64) == next_item_size as f64 {
        score -= 30.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item can't use this gap: the gap is likely dead space
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: square the residual waste so near-perfect fills dominate.
    score += (post_residual as f64 / cap).powi(2) * 30.0;

    // Reward bins whose residual is "shaped" by past placements (partially filled bins
    // are more valuable to close out than fresh ones).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 12.0;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits but not perfectly: bonus proportional to leftover after next,
            // amplified when the resulting residual is itself a common small size.
            let after = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (after as f64 / cap));
            if after > 0 && after <= 10 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here: penalize leaving residual just below next item size
            // (dead-space trap), scaled by how close it is to fitting.
            let gap = nxt - post_residual as f64;
            if gap < 10.0 {
                score += (10.0 - gap) * 1.5;
            }
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= fill_ratio * 20.0;
    }

    // Last-chance bin: if this is the only bin that fits the item, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        let mean_frac = (mean_residual / cap).clamp(0.01, 1.0);
        let pressure = (open_bins_count as f64) / mean_frac;
        // Penalize new bins early / when open bins still have plenty of room.
        score += 15.0 + pressure * 2.0;
        // But if the item is large and mean residual is low, new bin becomes attractive.
        score -= (item_size as f64 / cap) * 20.0 * (1.0 - mean_frac);
        // Extra guard: never open a new bin while a perfect fit exists among open bins.
        if post_residual == 0 && fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Perfect-fit magnet: a bin that closes exactly with this item is nearly unbeatable.
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Time horizon: late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post_residual as f64 / cap);

    // Global fragmentation: many open bins with high mean residual -> encourage using them up.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Small-residual harvesting: bins with tiny residuals are close to closure; prefer
    // placing items that nearly or exactly consume them over dumping into roomy bins.
    if bin_residual != bin_capacity && bin_residual as f64 <= cap * 0.25 {
        score -= 5.0 * (1.0 - (post_residual as f64 / bin_residual as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Squared waste: near-perfect fills dominate over merely decent ones.
    score += (post_residual as f64 / cap).powi(2) * 35.0;

    // Dead-space penalty: tiny nonzero gaps are worst-case leftovers.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 3.0;
    }

    // Reward tightness and partially-filled (shaped) bins, which are cheaper to close.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 12.0;

    // Lookahead: exact fit for the next item is a big win; near-miss residuals
    // just below next_item_size are dead-space traps.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / cap));
        } else if post_residual > 0 {
            let gap = nxt - pr;
            if gap < 10.0 {
                score += (10.0 - gap) * 1.5;
            }
        }
    } else {
        // Last item: close out the fullest bin.
        score -= fill_ratio * 20.0;
    }

    // Last-chance bin: strongly favor it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate: only attractive when open bins are fragmented or item is large.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (mean_residual / cap).max(0.01);
        score += 15.0 + pressure * 2.0;
        score -= (item_size as f64 / cap) * 20.0 * (1.0 - (mean_residual / cap).min(1.0));
        if post_residual == 0 {
            score -= 40.0;
        }
    } else {
        score -= 2.0 / open_bins_count.max(1) as f64;
    }

    // Late-stream consolidation: prefer filling existing bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (pr / cap);

    // Fragmentation relief: many open bins with high mean residual -> use them.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Mean residual coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual relative to capacity).
    let tight_fit = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (-tight_fit * 12.0).exp();

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it packs the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item won't fit here: penalize large dead space a bit
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(30.0);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "precious" —
    // using them for a large item is good; penalize wasting a large residual on a small item.
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score -= 0.15 * (res_f - mean_residual);
    } else {
        score += 0.15 * (mean_residual - res_f);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer open bins generally; only allow a fresh bin
    // when the item is large relative to capacity (poor fit everywhere likely).
    if bin_residual == bin_capacity {
        let open_bonus = 20.0 + 0.5 * open_bins_count as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // small/medium items: heavily penalize opening a new bin
        // large items (>70% of capacity): allow it more readily
        score += open_bonus * (1.0 - item_frac).max(0.0) * 2.0;
        // if next item is small, new bin can absorb leftovers later; slight relief
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    // Early in stream: slightly discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 && progress < 0.2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
