}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less dead space relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize small unusable post-residual gaps (dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty for wasting a scarce large residual.
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // Next item won't fit here; penalize leaving awkward leftover.
            score += 2.0;
        }
    }

    // Global state: prefer filling bins when many bins are open.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / 100.0);

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin; fill it.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early in stream, keep residuals flexible (penalize tiny leftovers);
    // late in stream, squeeze bins hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        score += (1.0 - progress) * 4.0 * (10.0_f64.min(post_residual as f64)) / 10.0;
        score -= progress * 5.0 * tightness;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 6.0 };
        score += desperation + 0.4 * (open_bins_count as f64);
        // Late stream: discourage opening new bins.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Squared waste: near-perfect fills dominate.
    score += (post_residual as f64 / cap).powi(2) * 30.0;

    // Partially filled bins are valuable to close out.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 14.0;

    // Lookahead: exact 2-step chain is best; near-exact also rewarded.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            if slack <= 3.0 {
                score -= 15.0; // near-exact chain: nearly as good
            }
        } else {
            let gap = nxt - post_residual as f64;
            if gap < 10.0 {
                score += (10.0 - gap) * 1.8; // dead-space trap just below next item
            }
        }
    } else {
        score -= fill_ratio * 22.0; // last item: pack fullest
    }

    // Tiny unusable residual is wasted space.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Prefer bins tighter than the mean residual.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate: only attractive when item is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let mr = (mean_residual / cap).clamp(0.01, 1.0);
        let pressure = open_bins_count as f64 * mr;
        score += 15.0 + pressure * 2.0;
        score -= (item_size as f64 / cap) * 22.0 * (1.0 - mr);
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 30.0;
        }
        // Late in the stream, opening new bins is cheap (bins won't be reused anyway).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    }

    // Fragmentation: many open bins with high mean residual -> use them up.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Time horizon: late stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post_residual as f64 / cap);

