}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual

    // Base: quadratic in post residual (prefer small leftovers, but not zero-waste obsession)
    let mut score = 2.0 * r + 0.08 * r * r;

    // Non-linear coupling: residual penalty modulated by stream progress.
    // Early on, tight packing matters less (many items left to fill gaps);
    // late in the stream, minimize dead space aggressively.
    let progress_coupling = (rn * rn) * (1.0 + 3.0 * progress * progress) * cap;
    score += progress_coupling;

    // Smooth sinusoidal-free polynomial term: reward near-full fits more as progress grows
    let fill = 1.0 - rn;
    score -= 30.0 * fill * fill * fill * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist
    // and early/mid stream; allow new bins late when residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual - rn * cap).abs() / cap;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 40.0 + 20.0 * (1.0 - progress) + 5.0 * open_pressure - 10.0 * fragmentation;
    } else {
        // Reward bins whose residual is above the mean (keeps big gaps available)
        let residual_diff = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * residual_diff * residual_diff - 4.0 * residual_diff;
    }

    // Lookahead coupling: if next item fits the post-residual, big reward (smooth poly)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if r >= nxt { 1.0 - (r - nxt) / cap } else { -((nxt - r) / cap) };
        score -= 15.0 * fit_next * fit_next.abs();
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
