    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 45.0;
        } else if pr >= nxt {
            // Bonus scaled by how cleanly the next item slots in.
            let after = pr - nxt;
            if after == 0.0 {
                score -= 30.0;
            } else {
                score -= 10.0 * (1.0 - after / cap);
            }
        } else {
            // Dead-space trap: residual just below next item size is wasted capacity.
            let gap = nxt - pr;
            if gap < 12.0 {
                score += (12.0 - gap) * 1.8;
            }
        }
        // Chain bonus: if the item after next could also fit post placement, add value.
        let after_next = pr.saturating_sub(next_item_size) as f64;
        if after_next > 0.0 && after_next >= 1.0 && after_next <= 20.0 {
            score -= 3.0;
        }
    } else {
        score -= fill_ratio * 22.0;
    }

    // Last-chance bin: strongly avoid opening a new bin when this is the only option.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate: open only when fragmentation pressure is real.
    if bin_residual == bin_capacity {
        let mean_res_ratio = (mean_residual / cap).clamp(0.01, 1.0);
        let pressure = open_bins_count as f64 * mean_res_ratio;
        // Base penalty keeps new bins from winning cheaply.
        score += 18.0;
        // High pressure (many open bins with room) => extra penalty.
        score += pressure * 3.0;
        // Large item with low mean residual => new bin becomes viable.
        let item_ratio = item_size as f64 / cap;
        if item_ratio > 0.6 && mean_res_ratio < 0.25 {
            score -= 30.0 * item_ratio;
        }
        // Late stream: new bins are costlier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Time horizon: late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 7.0 * (post_residual as f64 / cap);

    // Global fragmentation: many open bins with high mean residual -> use them up.
    if open_bins_count > 2 && mean_residual > 28.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Perfect-fit magnet: closing a bin exactly is always excellent.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
