        }
        // Second-order lookahead: if next item exactly fills the empty-bin alternative,
        // saving this bin for it is valuable — penalize consuming shaped space now.
        if next_item_size == bin_residual && bin_residual != bin_capacity {
            score += 6.0;
        }
    } else {
        score -= fill_ratio * 20.0;
    }

    // Last-chance bin: avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size) as f64 * 0.1;
