        score += 15.0 + pressure * 2.0;
        // Large items with low mean residual make a fresh bin attractive.
        score -= (item_size as f64 / cap) * 20.0 * (1.0 - mean_norm);
        // Late in the stream, opening new bins is almost always wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // If the item fits perfectly into some existing residual (fitting count high),
        // a new bin is clearly worse.
        if fitting_bins_count > 1 && item_size as f64 / cap > 0.7 {
            score += 10.0;
        }
    }

    // Time horizon: late stream consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * pr;

    // Global fragmentation: many open bins with high mean residual -> use them up.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Exact-fill bonus: consuming a bin entirely now is always excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class_size = cap / 10.0; // deciles of capacity
    let class_index = (pr / class_size).floor(); // 0..=10

    // Reward tight fits: post_residual class 0 (perfect) heavily rewarded,
    // class 1-2 (small waste) mildly rewarded.
    match class_index as u32 {
        0 => { score -= 40.0; }
        1 => { score -= 18.0; }
        2 => { score -= 8.0; }
        3 => { score += 4.0; }
        4 => { score += 10.0; }
        5 => { score += 16.0; }
        6 => { score += 22.0; }
        7 => { score += 28.0; }
        8 => { score += 34.0; }
        9 => { score += 40.0; }
        _ => { score += 48.0; }
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportionally to leftover dead space after both
            let double_left = (post_residual - next_item_size) as f64;
            score += double_left * 0.5;
        } else {
            // next item won't fit here: mild penalty scaled by overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(20.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream
    // and when many bins are open with usable residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * progress;
        if mean_residual > item_size as f64 {
            score += (mean_residual - item_size as f64).min(30.0);
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier bins).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * 10.0;
    }

    // Tie-break noise-free deterministic jitter via item size parity class.
    if item_size % 2 == 0 && post_residual % 5 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: square the residual waste so near-perfect fills dominate.
    score += (post_residual as f64 / cap).powi(2) * 30.0;

    // Reward bins whose residual is "shaped" by past placements.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 12.0;

    // Lookahead with two-step coupling: prefer bins that fit the next item
    // perfectly, or whose post-residual chains into a plausible future fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 40.0;
        } else if pr >= nxt {
            // Bonus scales with how well the leftover after next could still
            // hold a small item: reward "residual reusability".
            let after_next = pr - nxt;
            let reusability = if after_next >= 1.0 { (after_next / cap).min(0.25) } else { 0.0 };
            score -= 8.0 * (1.0 - after_next / cap) + reusability * 20.0;
        } else {
            // Dead-space trap: residual just below next item size.
            let gap = nxt - pr;
            if gap < 10.0 {
                score += (10.0 - gap) * 1.5;
            }
            // If the current item nearly fills this bin, closing it out is fine
            // even if next doesn't fit — soften the trap.
            if item_size as f64 / cap > 0.8 {
                score -= 6.0;
            }
        }
    } else {
        score -= fill_ratio * 20.0;
    }

    // Last-chance bin: avoid opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate: open only under fragmentation pressure or for large items
    // when open bins are nearly exhausted.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.01, 1.0);
        let pressure = (open_bins_count as f64) * mean_norm;
        let item_norm = item_size as f64 / cap;
        // Penalize new bins when many open bins hold plenty of slack.
        score += 15.0 + pressure * 2.0;
        // Large item + low aggregate slack makes a fresh bin attractive.
        let slack = mean_norm * open_bins_count as f64;
        if item_norm > 0.6 && slack < 2.0 {
            score -= 25.0 * item_norm * (1.0 - slack / 2.0);
        }
        score -= item_norm * 20.0 * (1.0 - mean_norm);
    }

    // Time horizon: late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post_residual as f64 / cap);

    // Global fragmentation: many open bins with high mean residual -> use them up.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
        // Extra nudge when several bins can fit the item: pick the tightest
        // (post_residual already encodes tightness, so just deepen the pull).
        if fitting_bins_count > 2 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can't hold even the
    // smallest plausible future item (<= 12) are "dead space".
    if post_residual < 12 {
        score += 40.0; // severe penalty for creating unusable slivers
    } else if post_residual < 25 {
        score += 12.0; // moderately risky gap
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Reward tight fits: the smaller post_residual relative to bin, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Open-bins pressure: with many open bins, prefer consolidating
    // into existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 * 0.6;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure.
        score += 30.0 + pressure;
    } else {
        score -= pressure.min(15.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a fresh bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the resulting residual,
    // reward heavily (chain fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mild reward proportional to how well it fills
        score -= (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > post_residual && post_residual < 12 {
        // residual too small for next item AND too small generally: extra penalty
        score += 15.0;
    }

    // Mean residual coupling: if this bin's post-residual is far below the
    // mean residual, we are compacting well; slight reward.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fewer items left to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Squared dead-space penalty: tiny gaps are worst, normalized by capacity.
    score += (pr / cap).powi(2) * 30.0;

    // Steep extra penalty for small nonzero gaps (classic dead-space trap).
    if pr > 0.0 && pr < 20.0 {
