    }

    // Reward tight fits: fill ratio discount.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 12.0;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Lookahead: exact fit for next item is excellent.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / cap));
        } else {
            // Next item can't use this gap: dead-space risk scaled by closeness.
            let gap = nxt - pr;
            if gap < 10.0 {
                score += (10.0 - gap) * 1.5;
            } else {
                score += 5.0;
            }
        }
    } else {
        // Last item: pack as fully as possible.
        score -= fill_ratio * 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins open or late in stream.
        let pressure = open_bins_count as f64 / (mean_residual / cap).max(0.01);
        score += 15.0 + pressure * 2.0 + 20.0 * progress;
        // Perfect-fill new bin is acceptable.
        if post_residual == 0 {
            score -= 40.0;
        }
        // Large item with low mean residual: new bin becomes attractive.
        score -= (item_size as f64 / cap) * 20.0 * (1.0 - (mean_residual / cap).min(1.0));
    } else {
        // Consolidation reward, stronger when many bins are open.
        score -= 2.0 / open_bins_count.max(1) as f64;
        if open_bins_count > 2 && mean_residual > 30.0 {
            score -= 4.0;
        }
    }

    // Prefer bins tighter than the global mean residual.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Late-stream consolidation pressure on residual waste.
    score += progress * 6.0 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
