    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0;
    }

    // New-bin candidate gating: cost depends on stream progress and how
    // fragmented the open bins are.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 {
            mean_residual / cap
        } else {
            0.0
