        score += 100.0 + 0.5 * item_size as f64 + 260.0 * progress + 90.0 * fragmentation;
        // If the next item cannot fit into any open bin's residual anyway,
        // opening a fresh bin is less harmful; soften the penalty slightly.
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // If the current item's fit in every open bin leaves a large
        // awkward residual, opening a fresh bin may be preferable.
        if next_item_size > 0 && open_bins_count > 2 && mean_residual < 0.05 * cap {
