    } else if post_class <= 5 {
        // residual 50..75: very reusable
        score -= 10.0;
    } else {
        // residual 75..100: excellent leftover
        score -= 14.0;
    }

    // Integer-division harmonic: how many items of the *current* size class
    // could still fit? More potential re-use -> reward.
    if item_size > 0 {
        let refills = post_residual / item_size;
        score -= 3.0 * refills as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a perfect pair placement -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // modulo-harmonic: penalize if slack lands in a dead class
            let slack_class = (slack as f64 / eighth).floor() as u32;
            score -= 12.0 - 2.0 * slack_class as f64;
