    // New-bin candidate handling: empty bins should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        // penalize opening a new bin, scaled by how many fitting alternatives exist
        score += 18.0 + 4.0 * fitting_bins_count as f64;
        // but if existing residuals are small relative to item, opening is fine
        if mean_residual < item_size as f64 * 1.1 {
            score -= 22.0;
        }
    }

    // Stream progression: near the end, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        score += 0.5 * post_residual as f64 * progress;
    }

