    // Lookahead: penalize leaving dead space that cannot host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space for the lookahead item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.4 * dead;
        } else {
            // Residual can host next item: reward.
            score -= 6.0;
            // Extra reward if the next item fills it exactly.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        }
