    // New-bin candidate gating: cost scales with progress and fragmentation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 270.0 * progress + 95.0 * fragmentation;
