pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: residual after placement, normalized
    let mut score = pr / cap;

    // Smooth non-linear waste penalty: dead space hurts super-linearly,
    // and progressively more as the stream advances.
    let waste = pr / cap;
    let waste_curve = waste * waste * (1.0 + 2.0 * progress);
    score += 1.5 * waste_curve;

    // Coupling of post_residual with mean residual: prefer bins whose
    // remaining space stays far from the mean (keeps diversity of sizes).
    let dev = (pr - mean_residual) / cap;
    score += 0.4 * dev * dev - 0.3 * dev;

    // Lookahead: reward if next item fits in post_residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 0.6 * (gap * gap);
        let fits_next = (pr >= next_item_size as f64) as f64;
        score -= 0.5 * fits_next * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // especially early/mid stream (avoid bin proliferation).
    let last_chance = (fitting_bins_count == 1 && is_new_bin < 0.5) as f64;
    score -= 2.5 * last_chance * (1.0 - 0.5 * progress);

    // New-bin candidate: penalize opening new bins smoothly, with a
    // polynomial relief term when open bins are crowded or residual is tiny.
    let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    let new_penalty = is_new_bin * (1.2 + 0.8 * progress * crowd);
    // Allow new bin when it would be nearly full (tight big item) or
    // when no existing bin fits well (large post_residual elsewhere).
    let relief = is_new_bin * (0.9 * (1.0 - waste).powi(3) + 0.5 * (1.0 - waste) * (mean_residual / cap));
    score += new_penalty - relief;

    // Mild reward for filling bins high as stream progresses (consolidation).
    score -= 0.3 * progress * (1.0 - waste) * (1.0 - is_new_bin);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
