            score -= 130.0 * (1.0 - slack / cap).powi(4);
            if slack == 0.0 {
                score -= 180.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 28.0 * (1.0 - slack / 30.0);
            }
