            if slack < 15.0 {
                score += 0.55 * (15.0 - slack);
            }
        } else {
            // Penalize post_residual too small to fit the next item.
            let miss = (nxt - pr).min(50.0);
            score += 0.6 * miss;
        }
    } else {
        // Last item: pure tightest fit.
        score -= 5.0;
    }

    // Best-fit style: prefer tighter bins relative to mean residual.
    let dev = mean_residual - bin_residual as f64;
    score += 0.35 * dev;

    // Last-chance bonus: only bin that fits — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate gating: cost scales with progress and fragmentation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
