        }
        // Large item relative to mean residual: loose fits fragment open bins.
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 35.0;
        }
        // Fresh bin allows perfect item+next pairing.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 60.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
