        // early packing stays exploratory while late packing consolidates.
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // NEW: usable-band shaping — a post-residual in [next_item, 100] is a
    // live target; reward keeping it there, penalize dropping just below it.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // residual still holds the next item: keep the chain alive
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            // residual is a partial trap: half of next item's size wasted
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // NEW: multi-item fill anticipation — if the residual can hold the item
    // plus a small extra item, prefer leaving a round-number residual that
