    if bin_residual != bin_capacity && pr > 60.0 && pr <= 100.0 && next_item_size > 0 && pr > next_item_size as f64 {
        score += 3.0 * (pr - 60.0) / 40.0 * (0.5 + 0.5 * progress);
    }

    // Prefer bins whose post-residual matches mean residual scale.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        if dev < 12.0 {
            score -= 2.2 * (1.0 - dev / 12.0);
        }
    }

    // MUTATION A: chain-aware new-bin arbitration. When a fresh bin's two-item
    // chain leaves a large tail but an open bin can host the item with a
    // better tail, penalize the fresh bin proportionally to the tail deficit.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress);
            }
        }
    }

