    // stream, a residual exactly matching the next item is worth much more.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // MUTATION C: small-item conservation — tiny items should almost never
    // open a fresh bin; they can plug gaps in nearly any residual.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // MUTATION D: residual pairing — reward leaving a residual that is a clean
    // multiple of the next item, enabling multi-item closure later.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // MUTATION E: compaction coupling — combine fine-grained residual fitting
    // with lookahead anticipation. When the post-residual is a usable band
    // (>= next item) AND the current fit is tight, compound the reward so
