        let nxt = next_item_size as f64;
        if pr >= nxt && pr <= 100.0 {
            let tight = item_size as f64 / bin_residual.max(1) as f64;
            score -= 5.5 * (pr / 100.0) * (0.4 + 0.6 * tight) * (1.0 - progress * 0.5);
        }
    }

    score
}

