        score -= 9.0 * (1.0 - pr / 12.0) * (0.5 + 0.5 * progress);
    }

    // MUTATION: fresh-bin tail arbitration refinement — also penalize fresh
    // bins when the current item alone strands >100 in a new bin while an
    // open bin could absorb the item entirely.
