    // a fresh bin; they can plug gaps in nearly any residual.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // MUTATION: residual pairing — reward leaving a residual that is a clean
    // multiple of the next item, enabling multi-item closure later.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 27): dead-space floor refinement — sharpen the unusable-band
    // penalty with a quadratic term so large stranded tails (e.g. residual 150+
    // after placing a mid item) are strongly avoided, since they are the main
    // source of the residual variance the parent still exhibits.
    if bin_residual != bin_capacity && pr > 100.0 && pr < cap {
        let dead = (pr - 100.0) / (cap - 100.0);
        score += 14.0 * dead * dead * (1.0 - progress);
    }

    // MUTATION (gen 27): mean-residual anchoring — when an open bin's resulting
    // post-residual deviates strongly above the fleet's mean residual, the bin
    // becomes an outlier that future items struggle to fill. Penalize outliers
    // mildly, reward bins that bring the fleet toward compact residuals.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dev = pr - mean_residual;
        if dev > 40.0 {
            score += 0.12 * (dev - 40.0);
        } else if dev < -20.0 && pr >= next_item_size as f64 {
            score -= 0.10 * (-dev - 20.0).min(60.0);
        }
    }

    // MUTATION (gen 27): dual-closure chain check for new bins — a fresh bin is
    // only attractive if its post-placement residual can still absorb the next
    // item with usable slack; otherwise defer to existing partial fills.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += 26.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // MUTATION (gen 27): endgame residual sweep — in the final stretch, prefer
    // bins whose post-residual stays below 100 (always fillable) with extra
    // weight, and penalize any residual that will likely strand capacity.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        if pr > 100.0 {
            score += 0.9 * (pr - 100.0);
        } else {
            score -= 3.0 * (1.0 - pr / 100.0);
        }
    }

    score
}

