        // barely fits anywhere else is often unavoidable; soften the penalty
        // so we don't over-fragment by cramming it into a poor open bin.
        if item_size as f64 > 0.75 * cap && fitting_bins_count > 0 {
            score -= 34.0 * (item_size as f64 / cap - 0.75) * 4.0;
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Penalize large unusable tails.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
