            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // NEW: dead-space harvest band — open bins whose residual is just above the
    // next item are prime compaction targets; push them harder mid-stream.
    if bin_residual != bin_capacity && next_item_size > 0 && pr >= next_item_size as f64 {
        let slack = pr - next_item_size as f64;
        if slack > 0.0 && slack <= 12.0 {
            score -= 14.0 * (1.0 - slack / 12.0) * (0.6 + 0.4 * progress);
        }
    }

