                    let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                    score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
                }
            }
        }
        // Dead-space ratio discipline for fresh bins.
        if fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            if tail > 0.0 && tail < 20.0 {
                score += (26.0 - 1.1 * tail) * (0.6 + 0.4 * progress);
            }
            if tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (tail / cap) * (1.0 - progress);
            }
            // NEW: dead-space ratio coupling — tail vs. mean residual gap.
            if tail > 0.0 && open_bins_count > 1 {
                let gap = tail - mean_residual;
                if gap > 25.0 {
                    score += 0.22 * (gap - 25.0) * (0.5 + 0.5 * progress);
                }
            }
        }
        // Three-item chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Penalize large unusable tails.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        score += 0.65 * (pr - 100.0) * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Mid-range gap penalties.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Two-item exact chain into an open bin.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-future usability of post-residual.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Residual multiple pairing.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Compaction pressure: prefer small post-residuals when many bins open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Wasted-space quadratic pressure for open bins (refined with dead-space ratio).
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
        // NEW: if the post-residual exceeds the mean residual across bins,
        // this bin is a dead-space outlier — extra quadratic pressure.
        if pr > mean_residual && open_bins_count > 2 {
            let excess = (pr - mean_residual) / cap;
            score += 6.0 * excess * excess * (open_bins_count as f64).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Small post-residual bonus band.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // Dead-space variance control among open bins.
    if bin_residual != bin_capacity && pr > 0.0 && open_bins_count > 3 {
        let dev = (pr - mean_residual).abs();
        if dev > 0.45 * cap {
            score += 0.05 * (dev - 0.45 * cap) * (0.5 + 0.5 * progress);
        }
    }

    // Endgame squeeze: late in the stream, prefer bins whose post-residual stays packable.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Fresh bin vs. usable alternative: discourage opening when a bin fits well.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
        // NEW: endgame fresh-bin discipline — late in the stream, strongly
        // prefer absorbing into open bins rather than spawning stragglers.
        if progress > 0.7 {
            score += 22.0 * (progress - 0.7) / 0.3 * (1.0 - best_use.min(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified for large items late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin sliver gating: avoid stranding dead space the next item can't use.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_pr = cap - item_size as f64;
            if fresh_pr < 12.0 && fresh_pr > 0.0 && fresh_pr < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_pr) / 12.0;
            }
        }
        // Dead-space ratio discipline for fresh bins.
        if fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            if tail > 0.0 && tail < 20.0 {
                score += (26.0 - 1.1 * tail) * (0.6 + 0.4 * progress);
            }
            if tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (tail / cap) * (1.0 - progress);
            }
        }
        // Three-item chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: a residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure: post residual equals 2*next exactly.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure: tighten acceptance when drifting above ideal density.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Three-item closure lookahead — reward near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let two = item_size as f64 + next_item_size as f64;
        if two < cap {
            let tail = bin_residual as f64 - two;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Penalize residuals that no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling — prefer bins whose post-residual leaves a
    // usable band rather than a sliver.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping — a post-residual in [next_item, 100] is a live target.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation — prefer round-number residuals small items absorb.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline — when many bins are open and the item fits
    // comfortably somewhere, make opening a fresh bin clearly worse.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / (mean_residual.max(1.0));
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration — penalize a fresh bin whose two-item
    // chain leaves a large tail, scaled by how many open bins could host the item.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation — tiny items should almost never open a fresh bin.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Residual pairing — reward residuals that are clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Unusable-band gradient — penalize the "just over 100" zone steeply.
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    // Residual-delta arbitration among open bins — prefer post-residuals
    // closest to a sizeable item (>= 20), steering toward future-closable states.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline — resist opening a bin that leaves a
    // large unusable tail unless no open bin fits.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - (item_size as f64).max(0.0);
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain closure — perfect two-bin sequence reward.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // MUTATION: compaction pressure — when many bins are open, penalize
    // bins that leave any post-residual, pushing fills toward full closure
    // and reducing residual variance across the fleet.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // MUTATION: dead-space variance control — avoid bins whose post-residual
    // deviates wildly from the fleet mean late in the stream, which strands
    // unusable pockets that inflate the final bin count.
    if bin_residual != bin_capacity && pr > 0.0 && open_bins_count > 3 {
        let dev = (pr - mean_residual).abs();
        if dev > 0.45 * cap {
            score += 0.05 * (dev - 0.45 * cap) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION: endgame squeeze — late in the stream, strongly prefer bins
    // whose post-residual stays packable by the next item; a stranded
    // residual at the tail end directly costs a whole bin.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    score
}

