                    * (mean_residual / cap).clamp(0.2, 1.0);
                // Counterweight: if the tail is a near-exact match for the next
                // item, opening is actually good — soften the penalty.
                if next_item_size > 0 && fresh_tail >= next_item_size as f64 {
                    let d = fresh_tail - next_item_size as f64;
                    if d <= 20.0 {
                        score -= 1.6 * (20.0 - d) * (1.0 - idle_prob);
                    }
                }
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Penalize large unusable tails.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        score += 0.65 * (pr - 100.0) * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
