    // residual choices toward the mean so remaining space aggregates into
    // fewer, larger reusable chunks instead of scattered slivers.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

