    // post-residual is exactly consumable by the next item plus the mean
    // leftover, i.e. likely to close completely within two placements.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let d = (pr - two_step).abs();
        if d <= 6.0 {
            score -= 2.4 * (6.0 - d) * (0.5 + 0.5 * progress);
        }
    }

