        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 8.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
        }
        // NEW: fresh-bin opening should be blocked when the item fits an open bin
        // whose resulting post-residual is small (near-closure), i.e. prefer
        // closing bins over spreading dead space.
        if fitting_bins_count > 0 {
            let best_close = open_bins_count as f64;
            if best_close > 0.0 && item_size as f64 >= 0.85 * mean_residual {
                score += 22.0 * (0.4 + 0.6 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Penalize large unusable tails.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        score += 0.65 * (pr - 100.0) * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
