        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Two-step residual exhaustion — reward bins whose post-residual is
    // exactly consumable by the sum of the next item and the mean leftover.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        if (pr - two_step).abs() <= 6.0 {
            score -= 2.4 * (6.0 - (pr - two_step).abs()) * (0.5 + 0.5 * progress);
        }
    }

    // NEW: dead-space closure sweep — when the post-residual lies in the
    // "stranded band" (too large for the next item but small in absolute
    // terms), add a progressive penalty that grows with how far the next
    // item under-fills it, scaled by remaining stream length. This pushes
    // selection toward bins whose residuals actually close.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr < 0.55 * cap {
            let underuse = (pr - nxt) / cap;
            score += 34.0 * underuse * underuse * (1.0 - progress) * (fitting_bins_count.min(4) as f64 * 0.25);
        }
    }

    // NEW: mean-residual alignment bonus — favor open bins whose resulting
    // post-residual lands close to the population mean residual, since such
    // bins are most likely to be exactly filled by future items.
    if bin_residual != bin_capacity && pr > 0.0 && mean_residual > 1.0 {
        let align = (pr - mean_residual).abs() / cap;
        score -= 6.0 * (1.0 - (align * 4.0).min(1.0)) * (0.4 + 0.6 * progress);
    }

    score
}

