            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Two-step residual exhaustion — reward bins whose post-residual is
    // exactly consumable by the sum of the next item and the mean leftover,
    // i.e. the bin will likely close completely within two placements.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        if (pr - two_step).abs() <= 6.0 {
            score -= 2.4 * (6.0 - (pr - two_step).abs()) * (0.5 + 0.5 * progress);
        }
    }

    // NEW: final-dead-space sweep — when nearly done, any residual above the
    // next item that cannot be closed by the mean leftover is pure waste;
    // penalize it sharply so remaining items consolidate into closable bins.
    if progress > 0.75 && bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if pr > nxt {
            let stranded = pr - nxt;
            if stranded > mean_residual * 1.5 {
                score += 0.9 * (stranded - mean_residual * 1.5).min(40.0) * (progress - 0.75) * 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: slack-based preference for post-residuals the next item nearly fills.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    }

    // Tightness reward with progress scaling.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Mean-residual coupling: prefer tighter bins.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 270.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open count, progress, fragmentation.
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        // Chain lookahead into a fresh bin.
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        // Small-item conservation: don't open fresh bins for tiny items.
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 55.0 * (1.0 - item_size as f64 / 15.0);
        }
        // Fresh-bin sliver gating: avoid stranding dead space the next item can't use.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_pr = cap - item_size as f64;
            if fresh_pr < 12.0 && fresh_pr > 0.0 && fresh_pr < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_pr) / 12.0;
            }
        }
        // Mid-stream new-bin discipline for large unusable tails.
        if next_item_size > 0 {
            let tail = cap - item_size as f64;
            if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
                score += 18.0 * (tail - 100.0) / cap;
            }
        }
        // Chain-aware arbitration with alternative-count scaling.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap {
                let fresh_tail = cap - chain;
                if fresh_tail > 60.0 {
                    let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                    score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
                }
            }
        }
        // Dead-space ratio discipline for fresh bins.
        if fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            if tail > 0.0 && tail < 20.0 {
                score += (26.0 - 1.1 * tail) * (0.6 + 0.4 * progress);
            }
            if tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (tail / cap) * (1.0 - progress);
            }
        }
        // Three-item chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Dead-space ratio of the fresh bin itself, with idle-probability weighting.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let idle_prob = (1.0 - fresh_tail / cap.max(1.0)).max(0.0);
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
                if next_item_size > 0 && fresh_tail >= next_item_size as f64 {
                    let d = fresh_tail - next_item_size as f64;
                    if d <= 20.0 {
                        score -= 1.6 * (20.0 - d) * (1.0 - idle_prob);
                    }
                }
            }
        }
        // Fresh-bin tail harvestability: reward tails that can absorb the
        // mean-sized leftover item rather than strand dead space.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
        }
        // MUTATION: stronger fresh-bin gating when an open bin can host the
        // item with a tail still usable by the next item (avoid premature opens).
        if fitting_bins_count > 0 && next_item_size > 0 && open_bins_count > 2 {
            let best_alt = fitting_bins_count;
            if best_alt > 1 && item_size as f64 <= mean_residual {
                score += 34.0 + 10.0 * (open_bins_count as f64).min(20.0) * 0.5;
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Penalize large unusable tails.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        score += 0.65 * (pr - 100.0) * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Mid-range gap penalties.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Two-item exact chain into an open bin.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-future usability of post-residual.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Residual multiple pairing.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Compaction pressure: prefer small post-residuals when many bins open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Wasted-space quadratic pressure for open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Small post-residual bonus band.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // Dead-space variance control among open bins.
    if bin_residual != bin_capacity && pr > 0.0 && open_bins_count > 3 {
        let dev = (pr - mean_residual).abs();
        if dev > 0.45 * cap {
            score += 0.05 * (dev - 0.45 * cap) * (0.5 + 0.5 * progress);
        }
    }

    // Endgame squeeze: prefer bins whose post-residual stays packable.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Fresh bin vs. usable alternative: discourage opening when a bin fits well.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Residual-dead-zone shaping: penalize orphan-band post-residuals.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Two-step residual exhaustion: reward bins closable within two placements.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        if (pr - two_step).abs() <= 6.0 {
            score -= 2.4 * (6.0 - (pr - two_step).abs()) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION: endgame exact-close bonus — very late in the stream, prefer
    // open bins whose post-residual exactly matches the next item so the bin
    // closes completely instead of leaving slivers.
    if progress > 0.75 && bin_residual != bin_capacity && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * (progress - 0.75) * 4.0;
    }

    score
}

