        }
        // NEW: penalize fresh-bin opening when a perfectly divisible pair
        // (item + next) leaves zero slack AND the mean residual pool could
        // have absorbed the item instead.
        if next_item_size > 0 && open_bins_count > 2 {
            let pair = (item_size + next_item_size) as f64;
            if pair <= cap && mean_residual >= item_size as f64 * 0.95 {
                score += 30.0 * (mean_residual / cap).min(1.0);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        score += 0.65 * (pr - 100.0) * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion: reward bins closable within two placements.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        if (pr - two_step).abs() <= 6.0 {
            score -= 2.4 * (6.0 - (pr - two_step).abs()) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // NEW: dead-space ratio refinement — penalize open bins whose post
    // residual is unmatchable by any plausible upcoming size band, scaled
    // by how much slack the mean-residual pool already carries.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt && pr > 0.0 {
            let stranded = (nxt - pr) / cap;
            let pool = (mean_residual / cap).clamp(0.0, 1.0);
            score += 20.0 * stranded * (1.0 - pool) * (0.4 + 0.6 * progress);
        }
        // NEW: reward bins whose post residual lies in a reusable band
        // (20–60) that typical mid-size items can still consume.
        if pr >= 20.0 && pr <= 60.0 && pr >= nxt {
            score -= 6.0 * (1.0 - progress) * (pr / 60.0);
        }
    }

    // NEW: global dead-space budget — when aggregate open-bin residual is
    // high relative to remaining demand, push placements that reduce it.
    if bin_residual != bin_capacity && total_items > step_index + 1 && next_item_size > 0 {
        let remaining = (total_items - step_index) as f64;
        let pool_per_bin = mean_residual / cap;
        if pool_per_bin > 0.35 && progress > 0.3 {
            let tight_fit = 1.0 - (pr / cap);
            score -= 8.0 * tight_fit * (pool_per_bin - 0.35) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Exact closure is always best.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Dead-space penalty for tiny unusable gaps.
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 3.0;
    }

    // Lookahead: next item exactly fills the remaining gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 480.0 * (1.0 + progress);
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 140.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 200.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 40.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
        } else {
            // Next item can't use this gap: dead space likely.
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    }

    // Tightness reward, stronger late in the stream.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (10.0 + 5.0 * progress) * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Mean residual coupling: prefer tighter bins.
    score += 0.35 * (mean_residual - bin_residual as f64);

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream.
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 90.0 + 0.5 * item_size as f64 + 240.0 * progress + 90.0 * fragmentation;
        if post_residual == 0 {
            score -= 900.0; // handled above but reinforce
        }
        // Chain feasibility: item + next fits nicely in a fresh bin.
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 100.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 80.0;
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.3 * (chain - cap).min(60.0);
            }
        }
        // If item is small relative to mean residual, opening a bin wastes capacity.
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        // Small items into fresh bins are wasteful when alternatives exist.
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 50.0 * (1.0 - item_size as f64 / 15.0);
        }
        // Fresh-bin dead-space quadratic pressure.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
            // Sliver gating: avoid stranding a tail the next item can't use.
            if next_item_size > 0 {
                let fresh_tail_n = cap - item_size as f64;
                if fresh_tail_n < 12.0 && fresh_tail_n > 0.0 && fresh_tail_n < next_item_size as f64 {
                    score += 40.0 * (12.0 - fresh_tail_n) / 12.0;
                }
            }
        }
    } else {
        // Open-bin consolidation pressure.
        if open_bins_count <= 3 {
            score -= 30.0;
        } else {
            score -= 2.0 / open_bins_count.max(1) as f64;
        }
        // Compaction pressure when many bins are open.
        if open_bins_count > 5 && pr > 0.0 {
            score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
        }
        // Two-step residual exhaustion: reward bins closable within two placements.
        if next_item_size > 0 && pr > 0.0 {
            let two_step = next_item_size as f64 + mean_residual;
            if (pr - two_step).abs() <= 6.0 {
                score -= 2.4 * (6.0 - (pr - two_step).abs()) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Large leftover gaps are wasteful.
    if pr > 100.0 {
        score += 1.0 * (pr - 100.0) * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Late exact-closure bonus.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 160.0 * (progress - 0.8) / 0.2;
    }

    // Small leftover bands.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Pair-fit into current bin: item + next exactly consumes residual.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 65.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Orphan-band shaping: penalize gaps that strand more than the next item needs.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Waste pressure on open bins, scaled by fit scarcity.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Next item fits comfortably: mild reward.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Fresh-bin guard: don't open when a good open-bin fit exists.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 6.0 * (open_bins_count as f64).min(20.0);
        }
    }

    score
}

