            score += 3.5 * (dead_frac - 1.0).min(3.0) * (0.4 + 0.6 * progress);
        } else {
            score -= 2.5 * (1.0 - dead_frac) * (pr / cap) * (1.0 - progress);
        }
    }

    // MUTATION: compaction tie-break — when several open bins fit, prefer the
    // smallest resulting residual scaled by remaining stream length.
    if bin_residual != bin_capacity && fitting_bins_count > 2 && pr > 0.0 {
        score -= 1.3 * (1.0 - pr / cap) * (1.0 - progress);
    }

    // MUTATION: fresh-bin gating refinement — resist opening a new bin when
    // the item leaves a tail larger than the largest plausible filler
    // (next item + mean residual), escalating with open-bin count.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let tail = cap - item_size as f64;
        let filler = next_item_size as f64 + mean_residual;
        if tail > filler && tail > 100.0 {
            score += 0.9 * (tail - filler) * ((open_bins_count as f64).min(10.0) / 10.0)
                * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
