            } else if frac_err <= 8.0 {
                score -= 1.5 * (8.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // When the fresh-bin tail exactly equals mean residual, the leftover
    // inventory can absorb it — mildly discourage opening a bin in that case.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // NEW: open-bin residual bucketing — bins whose post-residual falls in the
    // "hard-to-fill" band (just above typical small items) are penalized unless
    // the next item exactly consumes them; pushes selection toward bins whose
    // leftovers remain reusable by the mean-residual inventory.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt + 2.0 && pr < nxt + 14.0 && pr < 0.6 * cap {
            score += 0.5 * (pr - nxt - 2.0) * (1.0 - progress);
        }
    }

    // NEW: fresh-bin viability check — only open a new bin when the tail it
    // leaves can plausibly be filled by the residual inventory stream; a tail
    // much larger than mean_residual late in the stream is strongly discouraged.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && tail > mean_residual * 1.5 && progress > 0.5 {
            score += 6.0 * (tail - mean_residual * 1.5) / cap * progress;
        }
    }

    score
}

