    // Reward open bins whose post-residual is a near-multiple of the next item.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual: mildly discourage opening a bin.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // NEW: dead-space inventory coupling — penalize open bins whose dead space
    // exceeds what the remaining residual inventory can plausibly absorb,
    // with a sharper cubic term when inventory is scarce and progress is high.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        if dead > inventory {
            let excess = dead - inventory;
            score += 24.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
    }

    // NEW: residual bucketing refinement — instead of flat bands, reward bins
    // whose post-residual lands within a tolerance of the next item size plus
    // one mean-residual unit (harvestable in exactly two more steps), tuned by
    // remaining stream length.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let target = nxt + (mean_residual * 0.5).min(15.0);
        let d = (pr - target).abs();
        if d <= 10.0 {
            score -= 3.2 * (10.0 - d) * (1.0 - progress) * (1.0 - progress);
        }
    }

    // NEW: fresh-bin opening gate — when the fresh tail cannot be filled by the
    // next item and the mean residual is small, penalize opening more strongly
    // mid-stream, but relax it near the end where fresh bins are unavoidable.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let nxt = next_item_size as f64;
        if tail > nxt && tail - nxt > 25.0 {
            let inventory = (mean_residual / cap).clamp(0.0, 1.0);
            let gate = if progress > 0.75 {
                (1.0 - progress) * 4.0
            } else {
                1.0
            };
            score += 10.0 * ((tail - nxt) / cap) * (1.0 - inventory) * gate;
        }
    }

    // NEW: exact-fill chain across two open bins — reward a post-residual that
    // equals next_item + a small common divisor band, encouraging closure
    // cascades that leave near-zero waste.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > next_item_size as f64 {
        let rem = pr - next_item_size as f64;
        if rem > 0.0 && rem <= 12.0 {
            score -= 2.0 * (12.0 - rem) * (0.6 + 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
