    // available residual inventory elsewhere.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
        if next_item_size > 0 && pr > next_item_size as f64 {
            let stranded = pr - next_item_size as f64;
            score += 11.0 * (stranded / cap).powi(2) * (0.4 + 0.6 * progress);
        }
    }

    // Near-multiple lookahead closure on open bins (tightened band).
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 3.0 {
                score -= 7.5 * (3.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail vs mean-residual absorption gate.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // NEW: residual-alignment pairing — strongly prefer open bins whose
    // post-residual matches the mean residual band (these leftovers are
    // most likely to be consumed by the incoming size distribution),
    // weighted by stream progress.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 60.0 {
        let band = (pr - mean_residual).abs();
        if band <= 10.0 {
            score -= 2.2 * (10.0 - band) * (0.3 + 0.7 * progress);
        }
    }

    // NEW: endgame exact-fit sweep — late in the stream, post-residuals that
    // exactly equal the next item close bins perfectly; deepen the reward as
    // fewer fitting bins remain (scarcity of alternatives).
    if progress > 0.7 && post_residual == next_item_size && next_item_size > 0 {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score -= 55.0 * (progress - 0.7) / 0.3 * (0.5 + scarcity);
    }

    score
}

