    if bin_residual != bin_capacity && pr > 0.0 && mean_residual > 1.0 {
        let k = (pr / mean_residual).floor();
        if k >= 1.0 {
            let rem = pr - k * mean_residual;
            if rem < 6.0 {
                score -= 5.0 * (6.0 - rem) * (0.5 + 0.5 * progress) * (1.0 - (pr / cap));
