        }
    }

    // NEW: fresh-bin tail tiling by next item — when the tail after placing the
    // current item can be tiled by the next item size (2..=6 copies), reward
    // opening the bin since the tail will be fully consumed downstream.
    if bin_residual == bin_capacity && next_item_size > 1 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let nxt = next_item_size as f64;
        if tail > nxt {
            let k = (tail / nxt).floor();
            if k >= 2.0 && k <= 6.0 {
                let rem = tail - k * nxt;
                if rem == 0.0 {
                    score -= 30.0 * (1.0 - progress);
                } else if rem <= 5.0 {
                    score -= 12.0 * (5.0 - rem) / 5.0 * (1.0 - progress);
                }
            }
        }
    }

    // NEW: late-stream residual coalescing — bins whose post-residual is close
    // to the mean residual are preferred late, since pooled small items can
    // then close them; weight rises with progress and open-bin count.
    if bin_residual != bin_capacity && pr > 0.0 && progress > 0.5 {
        let dev = (pr - mean_residual).abs();
        let w = (open_bins_count as f64).min(12.0) / 12.0;
        score -= 3.5 * (1.0 - dev.min(30.0) / 30.0) * (progress - 0.5) * 2.0 * w;
    }

    score
}

