        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins — sharpened with a cubic term and
    // weighted by residual inventory scarcity so stranded slivers late in the
    // stream are penalized harder.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        let late = (0.35 + 0.65 * progress) * (1.0 + 0.5 * progress * progress);
        score += 16.0 * dead * dead * (1.0 - inventory) * late;
        score += 10.0 * dead * dead * dead * (1.0 - inventory) * progress;
    }

    // Reward open bins whose post-residual is a near-multiple of the next item
    // beyond the immediate fit (two-item lookahead closure); widened tolerance
    // and scaled by how many bins can still absorb the item.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 6.0 {
                let crowd = if fitting_bins_count > 2 { 1.3 } else { 1.0 };
                score -= 6.0 * (6.0 - frac_err) * (1.0 - progress) * crowd;
            }
        }
    }

    // When the fresh-bin tail exactly equals mean residual, the leftover
    // inventory can absorb it — mildly discourage opening a bin in that case.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // NEW: residual-variance-aware tiebreak — among open bins, prefer the one
    // whose post-residual sits closest to the mean residual when the mean is
    // small (high residual scarcity), promoting homogeneous closable leftovers.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 60.0 && mean_residual < 0.25 * cap {
        let dev = (pr - mean_residual).abs();
        score += 0.12 * dev * (1.0 - mean_residual / (0.25 * cap));
    }

    // NEW: penalize open bins whose post-residual falls into the classic
    // "unfillable band" (just below typical small-item sizes) weighted by
    // progress — these tails are the primary source of wasted space.
    if bin_residual != bin_capacity && pr > 0.0 {
        let band = (pr - 1.0).min(101.0 - pr);
        if band < 4.0 {
            score += 3.5 * (4.0 - band) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
