    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // MUTATION (combined): residual dead-space sharpening — penalize open-bin
    // post-residuals that no item in the plausible size band (next item ±
    // mean residual) can absorb, with a strandedness gradient. Combined with
    // a fine-grained usable-band bonus that rewards post-residuals which are
    // exactly one or two mean-residuals away from closure (compaction of
    // strays), scaled by how many bins are competing.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
        // Fine-grained compaction: reward tails closable by 2x mean residual
        // (i.e. two stray items), strongest when alternatives are plentiful.
        let two_mean = 2.0 * mean_residual;
        if pr > 0.0 && two_mean > 0.0 && (pr - two_mean).abs() <= 8.0 {
            let alt_w = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score -= 2.6 * (8.0 - (pr - two_mean).abs()) * alt_w * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (combined): mean-residual absorption bonus — reward a fresh
    // bin whose tail is almost exactly absorbable by next item + mean
    // leftover (consolidates strays), but only mid/early stream where
    // consolidation matters most.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 && progress < 0.85 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
        // Combined with lookahead: if the fresh-bin tail is unusable by the
        // next item AND exceeds the mean leftover inventory by more than
        // 100, it's a dead-tail trap — escalate with progress.
        let nxt = next_item_size as f64;
        if tail > nxt && tail - nxt > 100.0 {
            score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (combined): endgame compaction — in the final stretch prefer
    // the bin leaving the smallest unusable remainder, blended with a
    // fine-grained sliver guard that penalizes residuals just below the
    // next item size (dead slivers) harder as the stream ends.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
        if next_item_size > 0 && pr < next_item_size as f64 {
            score += 0.6 * (next_item_size as f64 - pr);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
