    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: dead-space budget accounting — track the cumulative "unfillable"
    // tail mass (residuals no item of size <= 100 can absorb) and penalize bins
    // whose post-residual contributes to it, scaled by remaining stream length.
    // This converts per-bin waste into a global compaction pressure.
    let remaining = (total_items - step_index.min(total_items)) as f64;
    let stream_density = (remaining / total_items.max(1) as f64).clamp(0.0, 1.0);
    if pr > 0.0 && pr < cap {
        let unfillable = (pr - 100.0).max(0.0);
        if unfillable > 0.0 {
            score += 0.30 * unfillable * stream_density;
        }
    }

    // MUTATION: cross-bin residual complementarity — when an open bin's
    // post-residual exactly matches the mean residual band (a typical leftover
    // can close it), reward it proportionally to how much inventory remains;
    // this steers packing toward bins that can be exactly finished by strays.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 100.0 && mean_residual > 0.0 {
        let dev = (pr - mean_residual).abs();
        if dev <= 12.0 {
            score -= 2.8 * (12.0 - dev) * (0.4 + 0.6 * stream_density);
        }
    }

    // MUTATION: large-item funnel — when the current item is large (> 60% of
    // capacity) and an open bin can take it, strongly prefer that over opening
    // a fresh bin whose tail would be tiny and stranded; but if the fresh tail
    // after this item can host the next item exactly, prefer the fresh bin.
    if item_size as f64 > 0.6 * cap {
        if bin_residual == bin_capacity {
            if next_item_size > 0 {
                let tail = cap - item_size as f64;
                if (tail - next_item_size as f64).abs() <= 2.0 {
                    score -= 90.0;
                } else if tail < next_item_size as f64 && fitting_bins_count > 0 {
                    score += 26.0 * (next_item_size as f64 - tail) / cap;
                }
            }
        } else {
            score -= 18.0 * (item_size as f64 / cap) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching (mutated weights).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 620.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 190.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating (mutated: stronger discipline, chain-aware).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        // MUTATION: fresh-bin dead-space quadratic pressure scaled by inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // MUTATION: strand-risk gate — tail unusable by next item and beyond
        // mean leftover inventory is a dead-tail trap; escalate with progress.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
        // Small-item conservation: don't waste a fresh bin on tiny items.
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 55.0 * (1.0 - item_size as f64 / 15.0);
        }
