            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus for fresh bins.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins — REINFORCED: widen band to
    // 130 and steepen the quadratic so mid-range residuals are more strongly
    // steered toward exact closure, attacking residual dead space.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 130.0 {
        let closeness = 1.0 - (pr / 130.0);
        score -= 8.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: exact-fit arbitration among competing bins — when several
    // bins fit, the one whose post-residual is an exact multiple of the next
    // item leaves a fully harvestable tail; reward multiplicativity up to 3x.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && next_item_size > 1 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if pr <= 3.0 * nxt + 1.0 {
            let m = (pr / nxt).round();
            if m >= 1.0 && (pr - m * nxt).abs() < 0.5 {
                score -= 9.0 * (1.0 + 0.5 * (1.0 - progress));
            }
        }
    }

    // MUTATION: fresh-bin open-count governor — when many bins are already
    // open and any existing bin can absorb the item with a small tail
    // (<= 25), opening a new bin strands inventory; add a graded penalty
    // that grows with open-bin count and shrinks with the best alternative
    // tail quality.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && open_bins_count > 3 {
        let best_tail = mean_residual.min(cap - item_size as f64).max(0.0);
        let tail_ok = (best_tail <= 25.0) as f64;
        score += tail_ok * (2.2 * (open_bins_count as f64).min(20.0)) * (0.4 + 0.6 * progress);
    }

    // MUTATION: late-stream zero-tail preference — after 70% of the stream,
    // any residual above the maximum plausible item size (100) is nearly
    // permanent waste; sharpen the linear penalty with a quadratic term.
    if bin_residual != bin_capacity && progress > 0.7 && pr > 100.0 {
        let waste = pr - 100.0;
        score += 0.9 * waste * waste / cap * (progress - 0.7) * 10.0;
    }

    score
}

