        }
    }

    // MUTATION (gen 42): fresh-bin over-opening brake — if the item already
    // fits in an open bin whose residual is at least the item size plus the
    // next item, opening a new bin wastes that co-fit capacity; penalize.
    if bin_residual == bin_capacity && open_bins_count > 0 && next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if mean_residual >= pair && fitting_bins_count > 0 {
            score += 24.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 42): residual variance sharpening — when the mean
    // residual is small (stream is nearly packed), push selection toward the
