    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling on open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus for fresh bins.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: mean-residual absorption steering on open bins — when a bin's
    // post-residual sits just below the sum of next item + mean leftover, it
    // will strand a sliver; when just above, it can be closed by a typical
    // stray. Reward the closable side, penalize the stranding side, scaled by
    // how much inventory actually remains.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let absorb = next_item_size as f64 + mean_residual;
        let diff = pr - absorb;
        if diff > 0.0 && diff <= 15.0 {
            score -= 2.6 * (15.0 - diff) * (1.0 - progress);
        } else if diff < 0.0 && diff > -15.0 {
            let inventory = (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 * (-diff) * (0.4 + 0.6 * inventory);
        }
    }

    // MUTATION: quadratic dead-tail gradient on open bins — residuals in the
    // awkward (60, 100] band are hard to fill with any single item but waste
    // real capacity; apply a rising quadratic penalty sharpened by progress.
    if bin_residual != bin_capacity && pr > 60.0 && pr <= 100.0 {
        let t = (pr - 60.0) / 40.0;
        score += 9.0 * t * t * (0.5 + 0.5 * progress);
    }

    // MUTATION: fresh-bin exact-pair gate refinement — when the fresh tail
    // after this item alone is unusable by the next item but small enough
    // that a typical stray (mean residual) would close it, mildly reward;
    // otherwise if the tail is a stranded sliver between next item and
    // mean residual, penalize to keep the item in an open bin instead.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let nxt = next_item_size as f64;
        if tail > nxt && tail - nxt < mean_residual {
            score += 3.0 * (mean_residual - (tail - nxt)) * (1.0 - progress);
        }
    }

    score
}

#[inline]
fn fresh_tail_check(slack: f64) -> bool {
    slack > 0.0 && slack < 15.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Two-step lookahead matching (borrowed strength from best-known).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 580.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 160.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 230.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 48.0 * (1.0 - slack / 30.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.35 * (miss - 60.0);
            }
        }
    }

    // Tightness reward, amplified late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (11.0 + 4.0 * progress) * tightness;

    // Deviation from mean residual (best-fit flavor).
    score += 0.36 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 260.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 260.0 * progress + 95.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 58.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 45.0;
        }
        // Chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 110.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 90.0;
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 55.0;
        }
        // Triple-chain exact closure into a fresh bin.
        if next_item_size > 0 {
            let tail = cap - item_size as f64 - next_item_size as f64;
            if tail == 0.0 {
                score -= 115.0;
            }
        }
        // Fresh-bin dead-space quadratic pressure scaled by remaining inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 25.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Strand-risk gate: fresh tail unusable by next item and beyond mean leftover.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.85 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
        // Small-item conservation.
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 50.0 * (1.0 - item_size as f64 / 15.0);
        }
    } else {
        if open_bins_count <= 3 {
            score -= 30.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        let unusable = pr - 100.0;
        score += 1.1 * unusable;
        score += 0.6 * unusable * (0.5 + 0.5 * progress);
    }

    score += progress * pr * 0.26;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.40 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Dead-zone guard: residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Exact two-item closure bonus.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 65.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 9.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus, amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.2;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.9 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 32.0;
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 6.5;
        } else if pr <= 40.0 {
            score += 4.5;
        } else if pr <= 60.0 {
            score -= 3.0;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 15.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 28.0 + 6.0 * (open_bins_count as f64).min(20.0);
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.7 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 170.0 * (progress - 0.8) / 0.2;
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.3 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.3 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.17 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.3 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // MUTATION: sliver-avoidance among competing open bins — prefer the bin
    // whose resulting residual is closest to zero, weighted by progress.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.0 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // MUTATION: two-step harvestability gate — an open bin whose post-residual
    // cannot absorb the next item even after donating mean-residual inventory
    // is a stranded tail; penalize proportionally, weighted by donatable stock.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.5 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // MUTATION: fresh-bin triple-closure anticipation — tail matching mean
    // residual within a tight band means a typical stray can close the bin.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.2 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: residual-band steering for open bins in the 40–70 band that
    // the next item cannot split — mild penalty to discourage stranding.
    if bin_residual != bin_capacity && pr > 40.0 && pr <= 70.0 && next_item_size > 0 && next_item_size as f64 > 20.0 {
        score += 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified for large items late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure scaled by remaining inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Strand-risk gate: dead-tail trap escalation.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: a residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling on open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers outside plausible band.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus for fresh bins.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction — smallest unusable remainder wins.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate — stranded tails weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins — steer toward exact closures.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: dual-lookahead consolidation — when an open bin's post-residual
    // can exactly absorb next item PLUS the mean leftover, prefer it strongly;
    // this couples fine-grained residual fitting with lookahead anticipation.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let target = next_item_size as f64 + mean_residual;
        if target <= 100.0 {
            let err = (pr - target).abs();
            if err <= 8.0 {
                score -= 3.0 * (8.0 - err) * (0.4 + 0.6 * progress);
            }
        }
    }

    // MUTATION: fresh-bin exact pair-closure with mean-residual margin —
    // opening a bin whose tail equals next item + mean residual exactly
    // consolidates all known inventory; reward it.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && tail <= mean_residual + 4.0 {
            score -= 14.0 * (1.0 - tail / (mean_residual + 4.0).max(1.0));
        }
    }

    // MUTATION: late-stream waste minimization — when few items remain,
    // prefer bins whose post-residual is smallest in absolute terms
    // (any leftover becomes permanent dead space).
    if progress > 0.7 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.35 * pr * (progress - 0.7) * (0.5 + 0.5 * (open_bins_count as f64).min(10.0) / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying with distance
        score -= 60.0 * (-diff / 8.0).exp();

        // Penalize leaving a residual that is too small for the next item (dead space)
        if (post_residual as i64) < (next_item_size as i64) {
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }

        // Mild bonus for residuals that could fit next item loosely
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: pure tight-fit packing
        score -= 20.0;
    }

    // Reward tight fits relative to mean residual across open bins
    if (post_residual as f64) < mean_residual {
        score -= 0.8 * (mean_residual - post_residual as f64);
    } else {
        score += 0.4 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting many open bins when a fresh bin could be better
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: expensive unless item is large and residual waste would be big
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64
        } else {
            post_residual as f64
        };
        // New bin starts at post_residual (= capacity - item_size); add handicap
        // so it only wins when open bins would leave clearly worse dead space.
        score += 15.0 + 0.5 * waste_penalty.min(40.0);
    }

    // Slight preference for compacting bins as the stream progresses
    score -= 3.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified for large items late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure scaled by remaining inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate — opening a bin whose tail is
        // unusable by the next item AND exceeds mean leftover inventory is a
        // dead-tail trap; escalate the penalty with progress.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: a residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling on open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers. Penalize open-bin
    // post-residuals that no item in the plausible size band (next item ±
    // mean residual) can ever absorb, with a gradient proportional to how
    // stranded the tail is.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus — when a fresh bin's tail is almost
    // exactly absorbable by the sum of next item + mean leftover, reward
    // opening it slightly (it consolidates strays instead of stranding).
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction — in the final stretch, prefer the bin that leaves
    // the smallest unusable remainder regardless of chain fit.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // MUTATION: two-step harvestability gate — an open bin whose post-residual
    // cannot absorb the next item even after donating mean residual inventory
    // is a stranded tail; penalize proportionally to the shortfall, weighted
    // by how much inventory actually remains to donate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // MUTATION: sliver-avoidance among competing open bins — when several bins
    // fit, prefer the one whose resulting residual is closest to zero modulo
    // typical item sizes, steering compaction toward exact closures.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // MUTATION: fresh-bin triple-closure anticipation — when the fresh tail
    // after placing the next item equals mean_residual within a tight band,
    // the bin can be exactly closed by a typical stray; reward it.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION (gen 43): dual-item residual exhaustion on open bins — when the
    // current item plus the next item leaves a residual exactly matching the
    // mean leftover strays, this bin closes perfectly in one more step;
    // reward the consolidation, weighted by how many strays remain.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 && progress < 0.9 {
        let pair = item_size as f64 + next_item_size as f64;
        if pair <= bin_residual as f64 {
            let after_pair = bin_residual as f64 - pair;
            let err = (after_pair - mean_residual).abs();
            if err <= 8.0 {
                score -= 2.8 * (8.0 - err) * (1.0 - progress) * (fitting_bins_count.min(4) as f64 * 0.25);
            }
        }
    }

    // MUTATION (gen 43): residual-band matching against mean residual — among
    // open bins, prefer the one whose post-residual sits closest to the mean
    // leftover when both are small, so future typical items can still close
    // them; penalize divergence only in the mid-stream window.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 100.0 && progress > 0.15 && progress < 0.75 {
        let dev = (pr - mean_residual).abs();
        if dev > 25.0 {
            score += 0.06 * (dev - 25.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): fresh-bin large-item routing — when the current item
    // is large relative to mean residual, opening a fresh bin for it strands
    // the open bins' residuals; instead reward routing large items into open
    // bins whose residual closely matches the item, and penalize fresh bins
    // for large items when open residuals could absorb them.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        let it = item_size as f64;
        if it > mean_residual * 1.2 && it > 0.5 * cap {
            score += 34.0 * (it / cap) * (1.0 - progress);
        }
    } else if bin_residual != bin_capacity && item_size as f64 > 0.5 * cap {
        let match_q = 1.0 - ((item_size as f64 - bin_residual as f64).abs() / cap);
        score -= 20.0 * match_q * match_q * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 43): endgame residual sweep — in the last fifth of the
    // stream, tiny post-residuals are nearly worthless; sharpen the gradient
    // so the smallest tail wins decisively among open bins.
    if progress > 0.8 && bin_residual != bin_capacity && pr > 0.0 && pr <= 15.0 {
        score -= 3.0 * (15.0 - pr) / 15.0 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward near-perfect fills (post_residual small relative to item).
    let perfect_fit = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - perfect_fit).powf(6.0) * (item_size as f64) * 0.6;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual wasted relative to lookahead: mild penalty.
        score += 0.1 * post_residual as f64 * (1.0 - t);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - t);
    }

    // When many bins fit the item, prefer the one with least residual waste.
    if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64);
        score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Global state: penalize opening new bins when open bins are already slack.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin attractive only if no good fit exists or item is huge relative to mean residual.
        let mean_gap = mean_residual - item_size as f64;
        let scarcity_bonus = if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        let gap_bonus = if mean_gap < 5.0 { 25.0 } else { -0.5 * mean_gap };
        score += 55.0 - scarcity_bonus - gap_bonus - 10.0 * t;
        // Late in stream, prefer consolidating into existing bins.
        score += 20.0 * t;
    }

    // Mild preference for fuller bins overall.
    score -= 0.15 * (bin_capacity as f64 - bin_residual as f64);

    // Small time-dependent tightness pressure: as stream ends, minimize bin count harder.
    score -= 8.0 * t * (bin_residual == post_residual + item_size) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified for large items late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure scaled by remaining inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: a residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling on open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: three-step closure lookahead — when the post-residual can be
    // exactly consumed by the next item plus a typical stray (mean_residual),
    // reward strongly; bins whose post-residual equals nxt + mean_residual
    // consolidate strays instead of stranding them.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let combo = nxt + mean_residual;
        if (pr - combo).abs() < 0.5 && pr <= 100.0 {
            score -= 30.0 * (1.0 - progress);
        }
        // Two-stray absorption: pr ≈ nxt + 2*mean_residual with tight tolerance.
        if (pr - nxt - 2.0 * mean_residual).abs() < 1.0 && pr <= 100.0 {
            score -= 12.0;
        }
    }

    // MUTATION: dead-space gradient escalation — refine the >100 waste band
    // with a steeper quadratic tail so bins leaving very large unusable
    // remainders are pushed to the back of the queue, especially mid-stream.
    if pr > 100.0 && bin_residual != bin_capacity {
        let excess = pr - 100.0;
        score += 0.012 * excess * excess * (0.4 + 0.6 * progress);
    }

    // MUTATION: tight-fit arbitration among many fitting bins — when several
    // open bins can host the item, sharpen the comparison of the resulting
    // residuals so the emptiest-but-wasteful bins lose out to compact fits.
    if bin_residual != bin_capacity && fitting_bins_count > 2 && pr > 0.0 {
        let compactness = 1.0 - (pr / cap).min(1.0);
        score -= 9.0 * compactness * compactness * (0.5 + 0.5 * progress);
    }

    // MUTATION: fresh-bin opening only when no open bin can later absorb the
    // item's own tail — if the fresh tail (cap - item) is far from anything
    // the next item plus mean residual could close, escalate the penalty with
    // the number of fitting alternatives.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let nxt = next_item_size as f64;
        if tail > nxt && tail - nxt > mean_residual + 40.0 {
            let alt_weight = (fitting_bins_count as f64).min(4.0) / 4.0;
            score += 10.0 * (tail - nxt - mean_residual - 40.0) / cap
                * alt_weight * (0.3 + 0.7 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, with non-linear (quadratic) waste cost
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth stream-progress coupling: later in the stream, waste matters more
    score += 6.0 * progress * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward tight fits: smooth exponential-like term via product of residuals
    let tightness = 1.0 - (pr / cap);
    score -= 8.0 * tightness * tightness * (item_size as f64 / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // mild preference among many candidates toward best fit already encoded
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward leaving space compatible with next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns).abs();
        score -= 5.0 * (-diff / 20.0) * (ns / cap);
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation
    let pressure = mean_residual / cap;
    score += 3.0 * pressure * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening a fresh bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    score += 0.38 * (mean_residual - bin_residual as f64);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
        // MUTATION: fresh-bin harvest window — reward tails in the compact
        // 20..=60 band that mean residual can plausibly close, since these
        // leave little dead space and absorb typical strays.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            if tail >= 20.0 && tail <= 60.0 {
                let closeness = 1.0 - (tail - mean_residual).abs() / 40.0;
                if closeness > 0.0 {
                    score -= 4.5 * closeness * (0.5 + 0.5 * progress);
                }
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: dead-space ratio arbitration — among fitting open bins,
    // penalize proportionally to the fraction of the bin that will remain
    // dead (post_residual relative to capacity), pushing selection toward
    // bins that get filled tighter, and escalate with open-bin count so
    // compaction wins when many bins compete.
    if bin_residual != bin_capacity && pr > 0.0 && fitting_bins_count > 0 {
        let dead_frac = pr / cap;
        let crowd = (open_bins_count as f64).min(12.0) / 12.0;
        score += 14.0 * dead_frac * (0.3 + 0.7 * crowd) * (0.4 + 0.6 * progress);
    }

    // MUTATION: exact pair-closure lookahead on open bins — if residual
    // minus item equals next item exactly, this is a two-step perfect
    // closure; reward strongly, slightly less than the immediate case.
    if bin_residual != bin_capacity && next_item_size > 0 {
        let rem = bin_residual as f64 - item_size as f64;
        if rem > 0.0 && (rem - next_item_size as f64).abs() < 0.5 {
            score -= 55.0 * (1.0 - progress);
        }
    }

    // MUTATION: fresh-bin large-item gate — when the item is large relative
    // to mean residual and no bin fits well, opening is fine, but if some
    // open bin leaves a small tail, prefer that; penalize opening when the
    // fresh tail would exceed 100 (unusable dead space for 1..=100 items)
    // and a fitting bin exists.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 {
            score += 26.0 * (tail - 100.0) / cap * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by integer division.
    // Classes: 0 (perfect fit), 1..=10 (tiny), 11..=25 (usable), 26..=50 (half-ish), >50 (large).
    let class = post_residual / 10;
    match class {
        0 => score -= 40.0,               // perfect or near-perfect fit: heavily reward
        1 => score -= 15.0,               // small dead space
        2 | 3 => score -= 5.0,            // moderate
        4 | 5 => score += 10.0,           // half-empty bin: penalize mildly
        _ => score += 25.0,               // large leftover: strong penalty
    }

    // Modulo-10 harmonic: residuals that are multiples of small item sizes are reusable.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 8.0;
    } else if m10 <= 2 {
        score -= 3.0;
    } else {
        score += m10 as f64 * 0.4;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 20.0 / (1.0 + gap as f64);
        } else {
            // next item won't fit here: penalize proportionally to overshoot class
            let over = (next_item_size - post_residual) / 10;
            score += 5.0 + over as f64 * 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin starts at a neutral baseline tied to mean state.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Prefer bins whose residual is close to the item (tight fit signal).
        let tightness = (bin_residual - item_size) as f64;
        score += 0.2 * (tightness - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    score += 0.38 * (mean_residual - bin_residual as f64);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
