        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // MUTATION: residual dead-space sharpening — penalize open-bin
    // post-residuals outside the plausible absorbable band, with gradient.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // MUTATION: mean-residual absorption bonus for fresh bins.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // MUTATION: endgame compaction — smallest unusable remainder wins.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // MUTATION: sliver-trap hardening — a post-residual in (0, next) that is
    // smaller than half the next item can never be closed by it and is likely
    // stranded; penalize proportionally, pushing toward usable bands.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        let nxt = next_item_size as f64;
        if pr < nxt * 0.5 {
            score += 1.2 * (nxt * 0.5 - pr) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION: fresh-bin consolidation bonus — exact tail match with next item.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail == next_item_size as f64 {
            score -= 90.0;
        }
    }

    // MUTATION (new): two-step harvestability gate — an open bin whose
    // post-residual cannot absorb the next item even after donating mean
    // residual inventory is a stranded tail; penalize the shortfall weighted
    // by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // MUTATION (new): sliver-avoidance among competing open bins — prefer the
    // bin whose resulting residual is closest to zero, steering toward exact
    // closures when multiple bins fit.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // MUTATION (new): fresh-bin triple-closure anticipation — when the fresh
    // tail after the next item nearly equals mean_residual, the bin can be
    // closed by a typical stray; reward it early/mid stream.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    }
    // Moderate gaps (10..20) are partially unusable for typical items; soft penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open,
    // encourage consolidation when few bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Early in stream, opening is cheaper; late, prefer filling existing bins.
        score += 20.0 * (1.0 - progress);
    } else {
        // Reward using existing bins, especially under pressure.
        score -= 4.0 + bin_pressure.min(12.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; penalize leaving awkward gaps.
        score += 5.0;
    }

    // Prefer bins with residuals close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified for large items late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure scaled by remaining inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: a residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling on open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: dead-space budget accounting — track the exact capacity waste
    // implied by choosing this bin. When the post-residual exceeds what any
    // plausible item (next item, mean residual, or the 1..=100 item band) can
    // absorb, charge the full stranded amount, amplified by how many open
    // bins could otherwise absorb the item instead.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score += 1.35 * stranded * alt * (0.45 + 0.55 * progress);
        }
    }

    // MUTATION: fresh-bin zero-waste chain gate — only open a new bin when the
    // tail after item+next is either exactly zero, small enough to be
    // absorbable by mean inventory, or the item genuinely fits nowhere well.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                // Tail within item-size band: potentially closable by a
                // typical future item — mild reward scaled by closeness.
                score -= 0.12 * (100.0 - tail);
            } else {
                // Large stranded tail: penalize harder mid-stream when
                // alternatives exist.
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // MUTATION: residual-efficiency tiebreak across competing open bins —
    // compare this bin's post-residual against the mean achievable residual;
    // reward bins that leave less than average, penalize those leaving more,
    // with weight growing as the stream progresses (compaction matters more
    // once the bin set is committed).
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION: large-item preference into tight residuals — when the item
    // consumes nearly all of the bin's residual, the resulting dead space is
    // minimal; grant a progressive bonus that scales with the fill fraction,
    // stronger when fewer fitting bins exist (avoid wasting scarce fits).
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 900.0; // two-item perfect packing
        } else if post > nxt {
            // leftover after next item: penalize dead space created
            score += 0.6 * (post - nxt);
            // still good if the remainder stays small
            if (post - nxt) <= 10.0 {
                score -= 120.0;
            }
        } else {
            // next item cannot follow into this bin
            score += 0.35 * (nxt - post);
        }
    } else {
        // last item: minimize residual as much as possible
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize spreading across many bins slightly; prefer consolidation
    if open_bins_count > 1 {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline penalty: opening new bin costs
        score += 180.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        } else if next_item_size > 0 && post_residual == next_item_size as f64 as u32 {
            score -= 450.0; // starting a bin that pairs perfectly with next item
        }
    }

    // Slight stream-progression pressure: later in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified for large items late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure scaled by remaining inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: a residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling on open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // Dead-space budget accounting — stranded amount beyond absorbable space,
    // amplified by alternative fits, refined with a smooth quadratic tail so
    // large stranded residuals are charged super-linearly.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            let s = stranded.min(cap);
            score += (1.35 * s + 0.012 * s * s) * alt * (0.45 + 0.55 * progress);
        }
    }

    // Fresh-bin zero-waste chain gate.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.12 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // Residual-efficiency tiebreak across competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // Large-item preference into tight residuals.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    // MUTATION: bin-pair consolidation pressure — when several open bins could
    // fit the item, prefer the one whose post-residual is closest to being
    // completely consumed by the *combined* future demand (next item plus a
    // fraction of mean residual). This drives residual space toward full
    // exhaustion rather than leaving mid-sized leftovers, directly targeting
    // the diagnosed dead-space weakness.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && next_item_size > 0 {
        let demand = next_item_size as f64 + 0.5 * mean_residual;
        let gap = (pr - demand).abs();
        if gap <= 25.0 {
            score -= 2.8 * (25.0 - gap) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION: endgame residual-exhaustion escalation — late in the stream,
    // any nonzero post-residual on an open bin is nearly permanent waste;
    // charge it progressively harder as the stream closes, but exempt the
    // sole fitting bin (it must be used regardless).
    if progress > 0.75 && bin_residual != bin_capacity && pr > 0.0 && fitting_bins_count > 1 {
        score += 3.2 * pr * (progress - 0.75) / 0.25 * 0.35;
    }

    // MUTATION: fresh-bin opening threshold coupled to open-bin saturation —
    // when many bins are open and their average residual can still hold the
    // item comfortably, opening a new bin is wasteful; escalate the penalty
    // with the ratio of item size to mean residual only when it is very low
    // (item tiny relative to available space), avoiding interference with the
    // existing large-item new-bin rewards.
    if bin_residual == bin_capacity && open_bins_count > 6 && fitting_bins_count > 1 && mean_residual > 0.0 {
        let ratio = item_size as f64 / mean_residual;
        if ratio < 0.35 {
            score += 40.0 * (0.35 - ratio) / 0.35 * (0.6 + 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified for large items late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure scaled by remaining inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: a residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling on open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION (gen 45, continued): dead-space budget accounting — track the exact
    // capacity waste implied by choosing this bin. When the post-residual exceeds
    // what any plausible item can absorb, charge the stranded amount, amplified by
    // how many open bins could otherwise absorb the item instead. Refined: the
    // absorbable ceiling now also accounts for a two-step chain (next item +
    // mean residual), so residuals closable over two placements are not overcharged.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let absorbable2 = (nxt + mean_residual).min(100.0).max(absorbable);
        let stranded = (pr - absorbable).max(0.0);
        let stranded2 = (pr - absorbable2).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            let two_step_relief = (stranded - stranded2).max(0.0);
            score += 1.35 * (stranded - 0.55 * two_step_relief) * alt * (0.45 + 0.55 * progress);
        }
    }

    // MUTATION (gen 45): fresh-bin zero-waste chain gate — only open a new bin when
    // the tail after item+next is exactly zero, absorbable by mean inventory, or
    // within the closable item band; large stranded tails are penalized harder
    // when alternatives exist, with weight sharpened by open-bin count.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.12 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                let bin_w = 1.0 + 0.04 * (open_bins_count.min(20) as f64);
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress) * bin_w;
            }
        }
    }

    // MUTATION (gen 45): residual-efficiency tiebreak across competing open bins —
    // compare this bin's post-residual against the mean achievable residual;
    // reward bins that leave less than average, penalize those leaving more,
    // with weight growing as the stream progresses.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 45): large-item preference into tight residuals — when the item
    // consumes nearly all of the bin's residual, the resulting dead space is
    // minimal; grant a progressive bonus scaled with the fill fraction, stronger
    // when fewer fitting bins exist.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    // NEW MUTATION (gen 45): three-step compaction lookahead — when the post-residual
    // can be exactly closed by next item + mean residual over two further
    // placements, reward the bin proportionally to how tight the closure is.
    // This targets the diagnosed weakness (suboptimal residual / dead-space ratio)
    // by preferring bins whose waste is recoverable within the near horizon.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let horizon = (next_item_size as f64 + mean_residual).min(cap);
        if pr > horizon {
            let overshoot = pr - horizon;
            if overshoot <= 25.0 {
                score += 1.1 * overshoot * (0.35 + 0.65 * progress);
            }
        } else {
            let slack = horizon - pr;
            if slack <= 8.0 {
                score -= 1.7 * (8.0 - slack) * (0.5 + 0.5 * progress);
            }
        }
    }

    // NEW MUTATION (gen 45): fresh-bin vs. best-open arbitration — when a new bin is
    // contemplated, compare the fresh tail after placing the item against the
    // smallest post-residual among open bins (approximated by mean_residual scaled
    // by scarcity of fits). If the fresh tail would strand more space than the
    // typical open-bin outcome, penalize proportionally; this sharpens the
    // decision boundary for opening bins mid-stream.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 0 {
        let fresh_tail = cap - item_size as f64;
        let open_outcome = mean_residual.min(100.0);
        let delta = fresh_tail - open_outcome;
        if delta > 0.0 && delta > next_item_size as f64 {
            score += 0.45 * (delta - next_item_size as f64) * (0.4 + 0.6 * progress);
        } else if delta <= 0.0 {
            score -= 0.9 * (-delta).min(40.0) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified for large items late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure scaled by remaining inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: a residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling on open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: dead-space budget accounting — track the exact capacity waste
    // implied by choosing this bin. When the post-residual exceeds what any
    // plausible item (next item, mean residual, or the 1..=100 item band) can
    // absorb, charge the full stranded amount, amplified by how many open
    // bins could otherwise absorb the item instead.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score += 1.35 * stranded * alt * (0.45 + 0.55 * progress);
        }
    }

    // MUTATION: fresh-bin zero-waste chain gate — only open a new bin when the
    // tail after item+next is either exactly zero, small enough to be
    // absorbable by mean inventory, or the item genuinely fits nowhere well.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.12 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // MUTATION: residual-efficiency tiebreak across competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION: large-item preference into tight residuals.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    // MUTATION (gen 45): two-item chain closure — when the next item exactly
    // exhausts the residual after placing the current one, this is a perfect
    // two-step seal; reward it strongly, especially early when bins are cheap
    // to preserve. Also reward near-exact seals within a small tolerance.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let after_next = pr - nxt;
        if after_next == 0.0 {
            score -= 45.0 * (1.0 + 0.6 * (1.0 - progress));
        } else if after_next > 0.0 && after_next <= 5.0 {
            score -= 3.2 * (5.0 - after_next) * (1.0 - progress);
        }
    }

    // MUTATION (gen 45): residual-echo arbitration — among open bins, prefer
    // the one whose post-residual is closest to the *mean of what remains
    // usable* (mean_residual), since that residual is most likely to be
    // matched by a future item of typical size. Penalize outliers
    // quadratically, scaled by how many alternatives exist.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 {
        let echo = (pr - mean_residual).abs();
        if echo > 8.0 {
            score += 0.16 * (echo - 8.0) * (echo - 8.0) / (mean_residual.max(10.0))
                * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 45): fresh-bin hoard guard — when many open bins still
    // hold usable residual (mean_residual large) and the current item is
    // small relative to the mean, opening a new bin strands capacity;
    // penalize proportionally to the stranded fraction, with a sharp
    // escalation when open_bins_count is high (compaction regime).
    if bin_residual == bin_capacity && fitting_bins_count > 0 && open_bins_count > 0 {
        let stranded_frac = (mean_residual / cap).clamp(0.0, 1.0);
        let small_item = (item_size as f64 / cap) < 0.35;
        if small_item && stranded_frac > 0.15 {
            let pressure = if open_bins_count > 6 { 1.6 } else { 1.0 };
            score += 34.0 * stranded_frac * pressure * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 45): endgame exact-harvest escalation — late in the
    // stream, every residual that can be exactly closed by the next item is
    // critical; deepen the existing escalation and extend it to near-exact
    // matches (within 2 units), which often arise from integer item streams.
    if next_item_size > 0 && pr > 0.0 && progress > 0.75 {
        let d = (pr - next_item_size as f64).abs();
        if d == 0.0 {
            score -= 40.0 * (progress - 0.75) / 0.25;
        } else if d <= 2.0 {
            score -= 12.0 * (2.0 - d) * (progress - 0.75) / 0.25;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal — strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual — amplified for large items late.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit style deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure scaled by remaining inventory.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space for 1..=100 items.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: a residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use — escalate with progress.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio coupling on open bins.
    if bin_residual != bin_capacity && pr > 0.0 {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        let waste = (pr / cap).min(1.0);
        score += 9.0 * waste * waste * alt_pressure * (0.3 + 0.7 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // Dead-space budget accounting — track the exact capacity waste implied by
    // choosing this bin. Amplified and made quadratic: stranded space beyond
    // what any plausible absorber (next item, mean residual, or the 100-item
    // band) can close grows super-linearly, with alternatives scaling.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            let norm = (stranded / 100.0).min(1.0);
            score += (1.35 * stranded + 22.0 * norm * norm) * alt * (0.45 + 0.55 * progress);
        }
    }

    // Fresh-bin zero-waste chain gate — refined with a graded absorbability
    // credit: tails closable by a plausible item get a smooth bonus instead of
    // a flat band, and the stranded-tail penalty sharpens with progress.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                let closeness = 1.0 - tail / 100.0;
                score -= 0.12 * (100.0 - tail) + 8.0 * closeness * (1.0 - progress);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // Residual-efficiency tiebreak across competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // Large-item preference into tight residuals.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    // MUTATION: dual-item lookahead waste projection — instead of only checking
    // whether the next item closes the residual, project the residual two
    // steps ahead (next item + mean-residual-sized item) and penalize any
    // irreducible remainder quadratically. This targets the diagnosed weakness
    // (suboptimal residual / dead-space ratio) by preferring bins whose
    // residual is exactly consumed by the next two plausible placements.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && progress < 0.95 {
        let nxt = next_item_size as f64;
        let second = mean_residual.max(1.0).min(100.0);
        let two_step_fill = nxt + second;
        let leftover = pr - two_step_fill;
        if leftover > 0.0 && leftover < 100.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
            score += 0.55 * leftover * (1.0 - leftover / 100.0) * alt * (0.4 + 0.6 * progress);
        } else if (leftover).abs() <= 2.0 {
            score -= 14.0 * (1.0 - progress);
        }
    }

    // MUTATION: fresh-bin open-bin drain gate — when opening a new bin, credit
    // it only if the remaining open-bin residual pool (mean residual times open
    // count) is too small to absorb the item plus a typical follow-up. If the
    // pool can plausibly hold the item, opening a new bin wastes that pool.
    if bin_residual == bin_capacity && open_bins_count > 0 && next_item_size > 0 {
        let pool = mean_residual * open_bins_count as f64;
        let demand = item_size as f64 + next_item_size as f64;
        if pool >= demand * 0.9 {
            score += 20.0 * (1.0 - progress) * ((pool / (demand * 1.5)).min(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching (borrowed from best).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // MUTATION: dead-space budget accounting — charge stranded capacity when
    // the post-residual exceeds what any plausible future item can absorb,
    // amplified by available alternatives and stream progress.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score += 1.35 * stranded * alt * (0.45 + 0.55 * progress);
        }
    }

    // MUTATION: fresh-bin zero-waste chain gate — only open a new bin when the
    // tail after item+next is exactly zero, absorbable by mean inventory,
    // within the item-size band, or the item genuinely fits nowhere well.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.12 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // MUTATION: residual-efficiency tiebreak across competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION: large-item preference into tight residuals — reward near-total
    // fills, stronger when fewer fitting bins exist.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Lookahead: exact match with next item, or graded slack rewards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 520.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 150.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 220.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 45.0 * (1.0 - slack / 30.0);
            }
            if slack < 12.0 {
                score += 0.8 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.55 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.35 * (miss - 60.0);
            }
        }
    }

    // Tightness reward relative to bin residual, scaled by progress.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (10.0 + 4.0 * progress) * tightness;

    // Large-fill preference into tight residuals.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            let alt_w = if fitting_bins_count == 1 { 1.5 } else { 1.0 };
            score -= 16.0 * (fill - 0.85) / 0.15 * alt_w;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 90.0 + 0.5 * item_size as f64 + 240.0 * progress + 90.0 * fragmentation;
        // Small-item conservation: don't waste a fresh bin on tiny items.
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 50.0 * (1.0 - item_size as f64 / 15.0);
        }
        // Chain feasibility: item + next fits well in a fresh bin.
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 100.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 90.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= mean_residual {
                    score -= 25.0 * (1.0 - fresh_slack / mean_residual.max(1.0));
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.25 * (chain - cap).min(60.0);
            }
