        }
        // Large unusable tails mid-stream: prefer existing bins.
        if next_item_size > 0 {
            let tail = cap - item_size as f64;
            if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
                score += 16.0 * (tail - 100.0) / cap;
            }
