        let closeness = 1.0 - (pr / 100.0);
        score -= 5.0 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // MUTATION: stranded-capacity accounting — charge leftover beyond what any
    // plausible future item (next or mean residual) can absorb, weighted by
    // available alternatives and stream progress.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score += 1.25 * stranded * alt * (0.45 + 0.55 * progress);
        }
    }

    // MUTATION: fresh-bin zero-waste chain gate — open a new bin only when the
    // tail after item+next is exactly zero, absorbable by mean inventory, or
    // modest; penalize large leftover tails when alternatives exist.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 24.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.10 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.8 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // MUTATION: compaction pressure when many bins are open — deprioritize
    // low-fill placements to consolidate.
    if bin_residual != bin_capacity && open_bins_count > 6 && pr > 0.0 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 {
            score += 9.0 * (0.5 - fill_ratio) * (0.4 + 0.6 * progress);
        }
    }

    score
}

