    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // Dead-space budget accounting — charge stranded capacity when the
    // post-residual exceeds what any plausible future item can absorb,
    // amplified by available alternatives and stream progress.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score += 1.35 * stranded * alt * (0.45 + 0.55 * progress);
        }
    }

    // Fresh-bin zero-waste chain gate.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.12 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // Residual-efficiency tiebreak across competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // Large-item preference into tight residuals.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    // MUTATION 1: squared stranded-dead-space escalation on open bins —
    // the diagnosed weakness is residual dead space; penalize it
    // super-linearly when no item of plausible size can ever close it,
    // stronger late when remaining inventory can't reshape it.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let inv = (mean_residual / cap).clamp(0.0, 1.0);
            score += 0.055 * stranded * stranded / cap * (1.0 + 1.5 * (1.0 - inv)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION 2: dead-space-aware bin choice — among open bins, prefer the
    // one whose post-residual lands closest to the mean residual band
    // (harvestable by future small items), a quadratic pull toward the
    // harvestable center rather than just minimizing pr.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let target = next_item_size as f64;
        let err = (pr - target).abs();
        if err > 0.0 && err <= 40.0 {
            score += 0.55 * err * (0.25 + 0.75 * progress) / (1.0 + (fitting_bins_count as f64).min(6.0) * 0.35);
        }
    }

    // MUTATION 3: fresh-bin opening gate sharpened — forbid opening a new bin
    // when the fresh tail after item+next is a known trap (positive but
    // below the smallest plausible item ~ mean_residual), yet reward exact
    // and near-exact chain closures more aggressively mid-stream.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.9 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        let floor_item = mean_residual.max(5.0);
        if tail > 0.0 && tail < floor_item {
            score += 30.0 * (1.0 - tail / floor_item) * (1.0 - progress);
        }
        if tail > 0.0 && tail <= 12.0 {
            score -= 4.0 * (12.0 - tail) * (1.0 - progress);
        }
    }

    // MUTATION 4: endgame residual sweep — in the final stretch, weight
    // post-residual waste super-linearly to squeeze the last bins.
    if progress > 0.75 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.85 * pr * pr / cap * (progress - 0.75) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // Dead-space budget accounting — charge stranded capacity when the
    // post-residual exceeds what any plausible future item can absorb,
    // amplified by available alternatives and stream progress.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score += 1.35 * stranded * alt * (0.45 + 0.55 * progress);
        }
    }

    // Fresh-bin zero-waste chain gate.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.12 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // Residual-efficiency tiebreak across competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // Large-item preference into tight residuals.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    // MUTATION 1: squared stranded-dead-space escalation on open bins —
    // super-linear penalty on residual dead space no plausible item can
    // close, stronger late when remaining inventory can't reshape it.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let inv = (mean_residual / cap).clamp(0.0, 1.0);
            score += 0.075 * stranded * stranded / cap * (1.0 + 1.5 * (1.0 - inv)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION 2: dead-space-aware bin choice — among open bins, prefer the
    // one whose post-residual lands closest to the next-item target, a
    // graded quadratic pull toward the harvestable center.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let target = next_item_size as f64;
        let err = (pr - target).abs();
        if err > 0.0 && err <= 40.0 {
            score += 0.62 * err * (0.25 + 0.75 * progress) / (1.0 + (fitting_bins_count as f64).min(6.0) * 0.35);
        }
    }

    // MUTATION 3: fresh-bin opening gate sharpened — forbid opening a new bin
    // when the fresh tail after item+next is a known trap (positive but
    // below the smallest plausible item ~ mean_residual), reward exact
    // and near-exact chain closures more aggressively mid-stream.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.9 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        let floor_item = mean_residual.max(5.0);
        if tail > 0.0 && tail < floor_item {
            score += 34.0 * (1.0 - tail / floor_item) * (1.0 - progress);
        }
        if tail > 0.0 && tail <= 12.0 {
            score -= 4.5 * (12.0 - tail) * (1.0 - progress);
        }
    }

    // MUTATION 4: endgame residual sweep — in the final stretch, weight
    // post-residual waste super-linearly to squeeze the last bins.
    if progress > 0.75 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.95 * pr * pr / cap * (progress - 0.75) * 4.0;
    }

    // MUTATION 5 (new): harvest-window conservation — when the current bin's
    // post-residual is the ONLY residual large enough to absorb the next
    // item among fitting bins, extra reward for keeping it usable; if the
    // post-residual would strand just below the next item, penalize
    // proportionally to how unique this bin's residual is.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt && fitting_bins_count <= 2 {
            score -= 9.0 * (1.0 - progress) * (pr / cap);
        }
        if pr < nxt && pr > nxt * 0.6 {
            let uniqueness = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 6.0 * (nxt - pr) * uniqueness * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION 6 (new): dual-closure lookahead on open bins — if this bin's
    // post-residual can absorb BOTH the next item and the mean residual
    // (two future small fills), give a compounding bonus scaled by how
    // scarce large residuals are across the open-bin pool.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let need = nxt + mean_residual;
        if pr >= need {
            let scarcity = 1.0 - (mean_residual / cap).min(1.0);
            score -= 8.0 * (1.0 - (pr - need) / cap) * scarcity * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // Dead-space budget accounting — charge stranded capacity.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score += 1.35 * stranded * alt * (0.45 + 0.55 * progress);
        }
    }

    // Fresh-bin zero-waste chain gate.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.12 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // Residual-efficiency tiebreak across competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // Large-item preference into tight residuals.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    // MUTATION 1 (refined): squared stranded-dead-space escalation — now also
    // gated by fitting-bin availability so stranded space is charged hardest
    // when the item could have gone elsewhere.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let inv = (mean_residual / cap).clamp(0.0, 1.0);
            let alt_w = if fitting_bins_count > 1 { 1.0 } else { 0.55 };
            score += 0.055 * stranded * stranded / cap * (1.0 + 1.5 * (1.0 - inv)) * (0.4 + 0.6 * progress) * alt_w;
        }
    }

    // MUTATION 2 (refined): dead-space-aware bin choice — quadratic pull of the
    // post-residual toward the next-item target, tighter band and stronger
    // weight when alternatives exist.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let target = next_item_size as f64;
        let err = (pr - target).abs();
        if err > 0.0 && err <= 40.0 {
            let alt_w = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
            score += 0.62 * err * err / 40.0 * (0.25 + 0.75 * progress) * alt_w;
        }
    }

    // MUTATION 3 (refined): fresh-bin opening gate — trap tails penalized
    // harder early, near-exact chain closures rewarded more mid-stream.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.9 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        let floor_item = mean_residual.max(5.0);
        if tail > 0.0 && tail < floor_item {
            score += 36.0 * (1.0 - tail / floor_item) * (1.0 - progress);
        }
        if tail > 0.0 && tail <= 12.0 {
            score -= 5.0 * (12.0 - tail) * (1.0 - progress);
        }
    }

    // MUTATION 4 (refined): endgame residual sweep — starts earlier (0.7) and
    // scales with open-bin count to concentrate compaction where it matters.
    if progress > 0.7 && bin_residual != bin_capacity && pr > 0.0 {
        let bin_w = 1.0 + 0.04 * (open_bins_count as f64).min(15.0);
        score += 0.85 * pr * pr / cap * (progress - 0.7) * 4.0 * bin_w;
    }

    // MUTATION 5 (new): harvest-band competition — among open bins, reward the
    // one whose post-residual can absorb the mean residual (a plausible future
    // small item), scaled by stream progress; this converts scattered slivers
    // into closable residuals instead of dead space.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let harvest = next_item_size as f64 + mean_residual;
        if pr >= harvest && pr - harvest <= 25.0 {
            score -= 0.9 * (25.0 - (pr - harvest)) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION 6 (new): fresh-bin vs. best-open tradeoff — when the best open
    // fit leaves a small post-residual (<= mean residual), opening a new bin is
    // wasteful; penalize the fresh-bin candidate proportionally.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && open_bins_count > 1 {
        let best_left = mean_residual.min(item_size as f64);
        if item_size as f64 <= mean_residual {
            score += 20.0 + 30.0 * (1.0 - item_size as f64 / mean_residual.max(1.0)) * (1.0 - progress);
        } else if best_left < 8.0 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // Dead-space budget accounting — charge stranded capacity when the
    // post-residual exceeds what any plausible future item can absorb,
    // amplified by available alternatives and stream progress.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score += 1.35 * stranded * alt * (0.45 + 0.55 * progress);
        }
    }

    // Fresh-bin zero-waste chain gate.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.12 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // Residual-efficiency tiebreak across competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // Large-item preference into tight residuals.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    // MUTATION 1: squared stranded-dead-space escalation on open bins —
    // super-linear penalty on dead space no plausible item can close,
    // stronger late when remaining inventory can't reshape it.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let inv = (mean_residual / cap).clamp(0.0, 1.0);
            score += 0.075 * stranded * stranded / cap * (1.0 + 1.5 * (1.0 - inv)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION 2: dead-space-aware bin choice — among open bins, penalize
    // post-residuals that miss the next-item target, softened by
    // alternatives count.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let target = next_item_size as f64;
        let err = (pr - target).abs();
        if err > 0.0 && err <= 40.0 {
            score += 0.62 * err * (0.25 + 0.75 * progress) / (1.0 + (fitting_bins_count as f64).min(6.0) * 0.35);
        }
    }

    // MUTATION 3: fresh-bin opening gate sharpened — forbid opening a new bin
    // when the fresh tail after item+next is a known trap, yet reward exact
    // and near-exact chain closures more aggressively mid-stream.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.9 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        let floor_item = mean_residual.max(5.0);
        if tail > 0.0 && tail < floor_item {
            score += 34.0 * (1.0 - tail / floor_item) * (1.0 - progress);
        }
        if tail > 0.0 && tail <= 12.0 {
            score -= 4.5 * (12.0 - tail) * (1.0 - progress);
        }
    }

    // MUTATION 4: endgame residual sweep — in the final stretch, weight
    // post-residual waste super-linearly to squeeze the last bins.
    if progress > 0.75 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.95 * pr * pr / cap * (progress - 0.75) * 4.0;
    }

    // MUTATION 5 (new): harvest-window matching — when the item nearly
    // exhausts the bin residual (fill >= 0.9), reward strongly proportional
    // to how close the leftover lands to a multiple of mean_residual,
    // steering leftovers into reusable bands instead of arbitrary slivers.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 100.0 {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill >= 0.9 {
            let band = mean_residual.max(4.0);
            let k = (pr / band).round();
            if k >= 1.0 {
                let dev = (pr - k * band).abs();
                score -= 2.8 * (1.0 - dev / band.max(1.0)).max(0.0) * (1.0 - progress);
            }
        }
    }

    // MUTATION 6 (new): anti-fragmentation lookahead on open bins — if the
    // post-residual is smaller than the next item but larger than half of it,
    // the residual is likely to strand; penalize proportionally to how much
    // of the next item it could have absorbed, weighted by open-bin pressure.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        let nxt = next_item_size as f64;
        if pr > 0.45 * nxt {
            let lost = nxt - pr;
            score += 0.9 * lost * (0.5 + 0.5 * progress) / (1.0 + (open_bins_count as f64) * 0.08);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching (borrowed from best).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain < cap && (cap - chain) > 100.0 && fitting_bins_count > 0 {
                score += 22.0 * ((cap - chain) - 100.0) / cap;
            }
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail < 12.0 && fresh_tail > 0.0 && fresh_tail < next_item_size as f64 {
                score += 40.0 * (12.0 - fresh_tail) / 12.0;
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
            }
            if fresh_tail > 55.0 && mean_residual < 0.35 * cap && open_bins_count > 2 {
                score += 14.0 * (fresh_tail / cap) * (1.0 - progress);
            }
            if fresh_tail >= next_item_size as f64 {
                let d = fresh_tail - next_item_size as f64;
                if d <= 20.0 {
                    score -= 1.6 * (20.0 - d) * (fresh_tail / cap);
                }
            }
        }
        // Triple-chain feasibility into a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair < cap {
                let third = mean_residual.min(30.0);
                if pair + third <= cap {
                    score -= 9.0 * (1.0 - (pair + third) / cap);
                }
            }
        }
        // Fresh-bin dead-space quadratic pressure.
        if fitting_bins_count > 0 {
            let fresh_tail = cap - item_size as f64;
            if fresh_tail > 0.0 {
                let dead_ratio = fresh_tail / cap;
                score += 26.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * progress)
                    * (mean_residual / cap).clamp(0.2, 1.0);
            }
        }
        // Fresh-bin strand-risk gate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let tail = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if tail > nxt && tail - nxt > 100.0 {
                score += 0.9 * (tail - nxt - 100.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        if open_bins_count <= 3 {
            score -= 33.0;
        } else {
            score -= 2.0 / open_bins_count as f64;
        }
    }

    // Waste-avoidance: residuals above 100 are dead space.
    if pr > 100.0 {
        score += 1.1 * (pr - 100.0);
        let unusable = pr - 100.0;
        score += 0.65 * unusable * (0.5 + 0.5 * progress);
    }
    if pr > 100.0 && pr <= 130.0 {
        score += (130.0 - pr) * (0.9 - 0.6 * progress);
    }

    score += progress * pr * 0.28;

    // Awkward gap: residual in (50,100] that next item can't close.
    if pr > 50.0 && pr <= 100.0 && next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 35.0 {
            score += 0.5 * (gap - 35.0);
        }
    }

    // Residual-scarcity coupling, scaled by item size.
    if bin_residual != bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).min(1.0);
        score += (0.42 + 0.003 * item_size as f64) * scarcity * pr;
    }

    // Reward plausible residual closure when alternatives exist.
    if next_item_size > 0 && pr == 0.0 && fitting_bins_count > 2 {
        score -= 40.0 * (1.0 - progress);
    }
    if pr > 0.0 && pr <= 100.0 && fitting_bins_count > 1 {
        score -= 13.0;
    }

    // Dead-zone guard: residual just under a typical item is a trap.
    if pr > 0.0 && pr < 20.0 && next_item_size > pr {
        score += 0.9 * (20.0 - pr);
    }

    // Mid-range residual trap.
    if pr > 25.0 && pr < 50.0 && next_item_size > 0 && post_residual != next_item_size {
        score += 0.34 * (pr - 25.0);
    }

    // Exact two-item closure bonus + near-exact triple closure.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 70.0;
        }
        if pair < cap {
            let tail = bin_residual as f64 - pair;
            if tail > 0.0 && tail <= 25.0 {
                score -= 10.0 * (1.0 - tail / 25.0);
            }
        }
    }

    // Near-closure bonus — amplified early.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let d = pr - next_item_size as f64;
        if d <= 4.0 {
            score -= (5.0 - d) * (1.0 - progress) * 4.4;
        }
    }

    // Endgame sharpening.
    if progress > 0.85 {
        score += 0.95 * progress * pr;
    }

    // Divisibility-aware closure.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if (pr - 2.0 * nxt).abs() < 0.5 && pr <= 100.0 {
            score -= 34.0;
        }
        if (pr - cap * 0.5).abs() < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - (pr - cap * 0.5).abs() / 6.0);
        }
    }

    // Bin-count pressure.
    if open_bins_count > 8 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio < 0.5 && bin_residual != bin_capacity {
            score += 10.5 * (0.5 - fill_ratio);
        }
    }

    // Residual-band steering.
    if pr > 0.0 && pr <= 100.0 {
        if pr <= 20.0 {
            score -= 7.0;
        } else if pr <= 40.0 {
            score += 5.0;
        } else if pr <= 60.0 {
            score -= 3.5;
        }
    }

    // Residual pairing — clean multiples of the next item.
    if next_item_size > 1 && pr > 0.0 && pr <= cap {
        let m = pr / next_item_size as f64;
        if m > 1.5 && (m - m.round()).abs() < 0.02 && m.round() <= 4.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Penalize residuals no plausible item can use.
    if pr > 100.0 && pr < cap {
        score += 0.55 * (pr - 100.0) * (0.4 + 0.6 * progress);
    }

    // Dead-space ratio penalty on open bins weighted by remaining inventory.
    if bin_residual != bin_capacity && pr > 0.0 {
        let dead = pr / cap;
        let inventory = (mean_residual / cap).clamp(0.0, 1.0);
        score += 16.0 * dead * dead * (1.0 - inventory) * (0.35 + 0.65 * progress);
    }

    // Usable-band shaping.
    if next_item_size > 0 && pr > 0.0 && pr <= 100.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / 100.0);
        } else if pr > nxt * 0.5 {
            score += 3.5 * (1.0 - pr / nxt);
        }
    }

    // Multi-item fill anticipation.
    if bin_residual != bin_capacity && pr > 0.0 && pr <= 30.0 {
        score -= 4.0 * (1.0 - pr / 30.0);
    }

    // New-bin discipline when item fits comfortably somewhere.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 0 {
        let best_use = item_size as f64 / mean_residual.max(1.0);
        if best_use <= 1.0 {
            score += 30.0 + 12.0 * (open_bins_count as f64).min(20.0) * 0.5;
        }
    }

    // Chain-aware new-bin arbitration.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let chain = (item_size + next_item_size) as f64;
        if chain < cap {
            let fresh_tail = cap - chain;
            if fresh_tail > 60.0 {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.6 };
                score += 1.8 * (fresh_tail - 60.0) * (0.5 + 0.5 * progress) * alt;
            }
        }
    }

    // Late-stream exact-closure escalation.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.8 {
        score -= 180.0 * (progress - 0.8) / 0.2;
    }

    // Small-item conservation.
    if bin_residual == bin_capacity && item_size <= 15 && fitting_bins_count > 0 {
        score += 55.0 * (1.0 - item_size as f64 / 15.0);
    }

    // Two-step residual exhaustion.
    if bin_residual != bin_capacity && next_item_size > 0 && pr > 0.0 {
        let two_step = next_item_size as f64 + mean_residual;
        let err = (pr - two_step).abs();
        if err <= 6.0 {
            score -= 2.4 * (6.0 - err) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-delta arbitration among open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let anchor = pr.max(20.0);
        score += 0.22 * (anchor - pr);
    }

    // Mid-stream new-bin discipline for large unusable tails.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64;
        if tail > 100.0 && progress > 0.25 && progress < 0.85 && fitting_bins_count > 0 {
            score += 18.0 * (tail - 100.0) / cap;
        }
    }

    // Triple-chain exact closure into a fresh bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail == 0.0 {
            score -= 120.0;
        }
    }

    // Orphan-band shaping for open bins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt && pr > 20.0 && pr < 0.75 * cap {
            let orphan = pr - nxt;
            if orphan > 10.0 {
                let var_w = (mean_residual / cap).clamp(0.1, 0.9);
                score += 0.32 * (orphan - 10.0) * (0.5 + var_w) * (0.4 + 0.6 * progress);
            }
        }
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 3.0 * (8.0 - (pr - nxt)) * (1.0 - progress);
        }
    }

    // Late-stream variance collapse toward the mean residual.
    if bin_residual != bin_capacity && progress > 0.6 && pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.18 * dev * (progress - 0.6) * 2.5;
    }

    // Endgame squeeze: avoid unfillable post-residuals late.
    if progress > 0.8 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.4 * (next_item_size as f64 - pr) * (progress - 0.8) * 5.0;
    }

    // Compaction pressure when many bins are open.
    if bin_residual != bin_capacity && open_bins_count > 5 && pr > 0.0 {
        score += (0.10 * (open_bins_count as f64).min(15.0)) * pr * (0.4 + 0.6 * progress);
    }

    // Near-multiple lookahead closure on open bins.
    if bin_residual != bin_capacity && next_item_size > 1 && pr > 0.0 && progress < 0.9 {
        let nxt = next_item_size as f64;
        let k = (pr / nxt).floor();
        if k >= 2.0 && k <= 5.0 {
            let frac_err = (pr - k * nxt).abs();
            if frac_err <= 4.0 {
                score -= 6.0 * (4.0 - frac_err) * (1.0 - progress);
            }
        }
    }

    // Fresh-bin tail matching mean residual.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 3.0 {
            score += 20.0 * (3.0 - (tail - mean_residual).abs()) / 3.0;
        }
    }

    // Residual dead-space sharpening — leftover slivers.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        let band_lo = nxt * 0.5;
        let band_hi = (nxt + mean_residual).min(100.0);
        if pr > band_hi {
            score += 0.8 * (pr - band_hi) * (0.4 + 0.6 * progress);
        } else if pr > 0.0 && pr < band_lo {
            score += 0.5 * (band_lo - pr) * (1.0 - progress);
        }
    }

    // Mean-residual absorption bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64;
        let absorb = next_item_size as f64 + mean_residual;
        if tail > 0.0 && (tail - absorb).abs() <= 10.0 {
            score -= 2.2 * (10.0 - (tail - absorb).abs());
        }
    }

    // Endgame compaction.
    if progress > 0.9 && bin_residual != bin_capacity && pr > 0.0 {
        score += 0.45 * pr * (progress - 0.9) * 10.0;
    }

    // Two-step harvestability gate.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let shortfall = next_item_size as f64 - pr;
        let donatable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.55 * shortfall * (1.0 - donatable) * (0.5 + 0.5 * progress);
    }

    // Sliver-avoidance among competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= 100.0 {
        let closeness = 1.0 - (pr / 100.0);
        score -= 5.5 * closeness * closeness * (0.6 + 0.4 * progress);
    }

    // Fresh-bin triple-closure anticipation.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.85 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 && (tail - mean_residual).abs() <= 6.0 {
            score -= 3.5 * (6.0 - (tail - mean_residual).abs()) * (1.0 - progress);
        }
    }

    // Dead-space budget accounting — charge stranded capacity when the
    // post-residual exceeds what any plausible future item can absorb,
    // amplified by available alternatives and stream progress.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            score += 1.35 * stranded * alt * (0.45 + 0.55 * progress);
        }
    }

    // Fresh-bin zero-waste chain gate.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        if tail > 0.0 {
            if tail <= mean_residual {
                score -= 26.0 * (1.0 - tail / mean_residual.max(1.0));
            } else if tail <= 100.0 {
                score -= 0.12 * (100.0 - tail);
            } else {
                let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
                score += 0.85 * (tail - 100.0) * alt * (0.4 + 0.6 * progress);
            }
        }
    }

    // Residual-efficiency tiebreak across competing open bins.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && pr > 0.0 && pr <= cap {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.30 * dev * (0.3 + 0.7 * progress);
        } else {
            score -= 0.30 * (-dev) * (0.3 + 0.7 * progress);
        }
    }

    // Large-item preference into tight residuals.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        if fill > 0.85 {
            score -= 18.0 * (fill - 0.85) / 0.15 * (1.0 + 0.5 * (fitting_bins_count == 1) as u8 as f64);
        }
    }

    // MUTATION 1 (refined): squared stranded-dead-space escalation on open
    // bins — super-linear penalty scaled by remaining inventory; tuned
    // coefficient up slightly since dead space is the diagnosed weakness.
    if bin_residual != bin_capacity && pr > 0.0 {
        let nxt = next_item_size as f64;
        let absorbable = nxt.max(mean_residual).max(1.0);
        let stranded = (pr - absorbable).max(0.0);
        if stranded > 0.0 {
            let inv = (mean_residual / cap).clamp(0.0, 1.0);
            score += 0.075 * stranded * stranded / cap * (1.0 + 1.6 * (1.0 - inv)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION 2 (refined): dead-space-aware bin choice — quadratic pull of
    // the post-residual toward the next-item closure target, softened when
    // many bins compete so the best fit still wins.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 {
        let target = next_item_size as f64;
        let err = (pr - target).abs();
        if err > 0.0 && err <= 40.0 {
            score += 0.60 * err * (0.25 + 0.75 * progress) / (1.0 + (fitting_bins_count as f64).min(6.0) * 0.35);
        }
    }

    // MUTATION 3 (refined): fresh-bin opening gate — forbid opening a new
    // bin when the fresh tail after item+next is a known trap (positive but
    // below the smallest plausible item ~ mean_residual), reward near-exact
    // chain closures more aggressively mid-stream.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 && progress < 0.9 {
        let tail = cap - item_size as f64 - next_item_size as f64;
        let floor_item = mean_residual.max(5.0);
        if tail > 0.0 && tail < floor_item {
            score += 34.0 * (1.0 - tail / floor_item) * (1.0 - progress);
        }
        if tail > 0.0 && tail <= 12.0 {
            score -= 4.5 * (12.0 - tail) * (1.0 - progress);
        }
    }

    // MUTATION 4 (refined): endgame residual sweep — super-linear waste
    // pressure in the final stretch, with a sharper ramp past 0.85.
    if progress > 0.75 && bin_residual != bin_capacity && pr > 0.0 {
        let ramp = if progress > 0.85 { 5.5 } else { 4.0 };
        score += 0.85 * pr * pr / cap * (progress - 0.75) * ramp;
    }

    // MUTATION 5 (new): harvest-window coupling — among open bins, reward
    // those whose post-residual can be exactly closed by the mean-residual
    // band (typical future item size), scaled by how many alternatives
    // exist; this directly targets residual dead-space reduction.
    if bin_residual != bin_capacity && pr > 0.0 && next_item_size > 0 && fitting_bins_count > 0 {
        let nxt = next_item_size as f64;
        let harvest_target = (nxt + mean_residual).min(cap);
        if (pr - harvest_target).abs() <= 8.0 {
            let alt = if fitting_bins_count > 1 { 1.0 } else { 0.5 };
            score -= 3.2 * (8.0 - (pr - harvest_target).abs()) * alt * (0.5 + 0.5 * progress);
        }
        // Penalize post-residuals that strand the mean-residual band:
        // residual too small for a typical item yet too large to be waste-free.
        if pr > 0.0 && pr < nxt && pr > nxt * 0.4 {
            score += 2.0 * (pr / nxt) * (0.4 + 0.6 * progress) * (fitting_bins_count.min(4) as f64 * 0.25);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 610.0;
            if progress > 0.8 {
                score -= 180.0 * (progress - 0.8) / 0.2;
            }
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 180.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 245.0;
            }
            if slack > 0.0 && slack <= 30.0 {
                score -= 52.0 * (1.0 - slack / 30.0);
            }
            if slack < 15.0 {
                score += 0.8 * (15.0 - slack);
            }
            if slack > 0.0 && slack <= 100.0 {
                score -= 24.0 * (slack / 100.0);
            }
            if slack > 0.0 && slack < 12.0 {
                score += 0.9 * (12.0 - slack);
            }
        } else {
            let miss = nxt - pr;
            score += 0.6 * miss.min(50.0);
            if miss > 60.0 {
                score += 0.38 * (miss - 60.0);
            }
        }
    } else {
        score -= 5.0;
    }

    // Tightness reward relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= (12.0 + 4.5 * progress) * tightness;

    // Best-fit deviation from mean residual.
    score += 0.38 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 270.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 100.0 + 0.5 * item_size as f64 + 268.0 * progress + 98.0 * fragmentation;
        if next_item_size > 0 && fitting_bins_count <= 1 {
            score -= 62.0;
        }
        if open_bins_count > 0 && item_size as f64 > 1.6 * mean_residual {
            score -= 48.0;
        }
        if next_item_size > 0 {
            let chain = (item_size + next_item_size) as f64;
            if chain <= cap {
                let fresh_slack = cap - chain;
                score -= 115.0 * (1.0 - fresh_slack / cap);
                if fresh_slack == 0.0 {
                    score -= 95.0;
                }
                if fresh_slack > 0.0 && fresh_slack <= 100.0 {
                    score -= 14.0 * (fresh_slack / 100.0);
                }
                if fresh_slack > 0.0 && fresh_slack < 15.0 {
                    score += 0.7 * (15.0 - fresh_slack);
                }
            } else {
                score += 0.28 * (chain - cap).min(60.0);
            }
        }
        if open_bins_count > 4 && mean_residual < 0.08 * cap {
            score -= 60.0;
        }
        if open_bins_count > 0 && item_size as f64 > 0.9 * mean_residual {
            score -= 14.0 * (item_size as f64 / cap);
        }
        // Fresh-bin tail harvestability.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_tail = cap - item_size as f64;
            let harvest = (mean_residual + next_item_size as f64).min(cap);
            if fresh_tail >= harvest {
                score -= 7.0 * (1.0 - (fresh_tail - harvest) / cap) * (1.0 - progress);
            }
            if fresh_tail > 0.0 && fresh_tail < 20.0 {
                score += (26.0 - 1.1 * fresh_tail) * (0.6 + 0.4 * progress);
